--
-- Name: assert_customer_address_consistent(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assert_customer_address_consistent(p_address_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_addr      public.customer_addresses%ROWTYPE;
  v_cust_rid  uuid;
BEGIN
  SELECT a.* INTO v_addr
    FROM public.customer_addresses a
   WHERE a.id = p_address_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT c.restaurant_id INTO v_cust_rid
    FROM public.customers c
   WHERE c.id = v_addr.customer_id;

  IF v_cust_rid IS NULL THEN
    RAISE EXCEPTION
      'customer_addresses % points at a customer that does not exist',
      p_address_id USING ERRCODE = 'check_violation';
  END IF;

  IF v_cust_rid <> v_addr.restaurant_id THEN
    RAISE EXCEPTION
      'customer_addresses % belongs to tenant %, the customer has %',
      p_address_id, v_addr.restaurant_id, v_cust_rid USING ERRCODE = 'check_violation';
  END IF;
END;
$$;


--
-- Name: FUNCTION assert_customer_address_consistent(p_address_id uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.assert_customer_address_consistent(p_address_id uuid) IS 'Re-checks at COMMIT that customer_addresses.restaurant_id matches its customer''s restaurant_id. Called by public.customer_addresses_assert_consistency.';


--
-- Name: assert_order_delivery_consistent(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assert_order_delivery_consistent(p_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_d        public.order_deliveries%ROWTYPE;
  v_order_rid uuid;
  v_order_type text;
  v_cust_rid  uuid;
  v_cour_rid  uuid;
BEGIN
  SELECT d.* INTO v_d
    FROM public.order_deliveries d
   WHERE d.order_id = p_order_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT o.restaurant_id, o.order_type
    INTO v_order_rid, v_order_type
    FROM public.orders o
   WHERE o.id = p_order_id;

  IF v_order_type IS DISTINCT FROM 'delivery' THEN
    RAISE EXCEPTION
      'order % is not delivery (it is %s), cannot carry an order_deliveries row',
      p_order_id, v_order_type USING ERRCODE = 'check_violation';
  END IF;

  IF v_order_rid <> v_d.restaurant_id THEN
    RAISE EXCEPTION
      'order_deliveries % (tenant %) belongs to order % (tenant %)',
      p_order_id, v_d.restaurant_id, p_order_id, v_order_rid USING ERRCODE = 'check_violation';
  END IF;

  SELECT c.restaurant_id INTO v_cust_rid
    FROM public.customers c
   WHERE c.id = v_d.customer_id;

  IF v_cust_rid IS NULL THEN
    RAISE EXCEPTION
      'order_deliveries % points at a customer that does not exist',
      p_order_id USING ERRCODE = 'check_violation';
  END IF;

  IF v_cust_rid <> v_d.restaurant_id THEN
    RAISE EXCEPTION
      'order_deliveries % customer is in tenant %, not %',
      p_order_id, v_cust_rid, v_d.restaurant_id USING ERRCODE = 'check_violation';
  END IF;

  IF v_d.courier_id IS NOT NULL THEN
    SELECT co.restaurant_id INTO v_cour_rid
      FROM public.couriers co
     WHERE co.id = v_d.courier_id;

    IF v_cour_rid IS NULL THEN
      RAISE EXCEPTION
        'order_deliveries % points at a courier that does not exist',
        p_order_id USING ERRCODE = 'check_violation';
    END IF;

    IF v_cour_rid <> v_d.restaurant_id THEN
      RAISE EXCEPTION
        'order_deliveries % courier is in tenant %, not %',
        p_order_id, v_cour_rid, v_d.restaurant_id USING ERRCODE = 'check_violation';
    END IF;
  END IF;
END;
$$;


--
-- Name: FUNCTION assert_order_delivery_consistent(p_order_id uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.assert_order_delivery_consistent(p_order_id uuid) IS 'Re-checks at COMMIT that the order is delivery and that order_deliveries / orders / couriers / customers all share the same tenant. Called by public.order_deliveries_assert_consistency.';


--
-- Name: assert_payment_consistent(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assert_payment_consistent(p_payment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_payment    public.payments%ROWTYPE;
  v_line_count integer;
  v_amount_sum bigint;
  v_change_sum bigint;
BEGIN
  SELECT p.* INTO v_payment
    FROM public.payments p
   WHERE p.id = p_payment_id;

  -- The payment itself is gone: its tender lines went with it (ON DELETE
  -- CASCADE), so there is nothing left to reconcile.
  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT count(*),
         coalesce(sum(t.amount), 0),
         coalesce(sum(t.cash_received - t.amount)
                  FILTER (WHERE t.method_kind = 'cash'), 0)
    INTO v_line_count, v_amount_sum, v_change_sum
    FROM public.payment_tenders t
   WHERE t.payment_id = p_payment_id;

  IF v_line_count = 0 THEN
    RAISE EXCEPTION
      'payment % has no tender lines: a payment is at least one line applied to the bill',
      p_payment_id USING ERRCODE = 'check_violation';
  END IF;

  IF v_amount_sum <> v_payment.total_charged THEN
    RAISE EXCEPTION
      'payment % charges % but its tender lines add up to %',
      p_payment_id, v_payment.total_charged, v_amount_sum USING ERRCODE = 'check_violation';
  END IF;

  IF v_change_sum <> v_payment.change_given THEN
    RAISE EXCEPTION
      'payment % records % of change but its cash tender lines give %',
      p_payment_id, v_payment.change_given, v_change_sum USING ERRCODE = 'check_violation';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.orders o
     WHERE o.id = v_payment.order_id
       AND o.restaurant_id = v_payment.restaurant_id) THEN
    RAISE EXCEPTION
      'payment % settles an order that belongs to another restaurant',
      p_payment_id USING ERRCODE = 'check_violation';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.cash_registers c
     WHERE c.id = v_payment.cash_register_id
       AND c.restaurant_id = v_payment.restaurant_id) THEN
    RAISE EXCEPTION
      'payment % was taken on a cash register that belongs to another restaurant',
      p_payment_id USING ERRCODE = 'check_violation';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.payment_tenders t
     WHERE t.payment_id = p_payment_id
       AND t.restaurant_id <> v_payment.restaurant_id) THEN
    RAISE EXCEPTION
      'payment % has a tender line that belongs to another restaurant',
      p_payment_id USING ERRCODE = 'check_violation';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.payment_tenders t
     WHERE t.payment_id = p_payment_id
       AND NOT EXISTS (SELECT 1 FROM public.payment_methods m
                        WHERE m.id = t.payment_method_id
                          AND m.restaurant_id = v_payment.restaurant_id)) THEN
    RAISE EXCEPTION
      'payment % has a tender line whose payment method belongs to another restaurant',
      p_payment_id USING ERRCODE = 'check_violation';
  END IF;
END;
$$;


--
-- Name: FUNCTION assert_payment_consistent(p_payment_id uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.assert_payment_consistent(p_payment_id uuid) IS 'Re-computes the cross-row invariants of one payment (tender sum = total_charged, change_given = the cash overshoot, at least one line, one restaurant across payment/order/register/tender/catalog) and raises check_violation (23514) when one fails. Called at COMMIT by public.payments_assert_consistency.';


--
-- Name: backfill_inventory_opening(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.backfill_inventory_opening() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_item  record;
  v_loc   uuid;
  v_lot   uuid;
  v_count integer := 0;
BEGIN
  FOR v_item IN
    SELECT i.id, i.restaurant_id, i.stock, COALESCE(i.cost, 0) AS cost
      FROM public.ingredients i
     WHERE i.stock <> 0
       AND NOT EXISTS (SELECT 1 FROM public.inventory_lots l WHERE l.ingredient_id = i.id)
     ORDER BY i.restaurant_id, i.id
  LOOP
    v_loc := private.ensure_default_inventory_location(v_item.restaurant_id);

    INSERT INTO public.inventory_lots (restaurant_id, ingredient_id, location_id, quantity, unit_cost)
    VALUES (v_item.restaurant_id, v_item.id, v_loc, v_item.stock, greatest(v_item.cost, 0))
    RETURNING id INTO v_lot;

    INSERT INTO public.inventory_movements
      (restaurant_id, ingredient_id, location_id, lot_id, movement_type, quantity,
       unit_cost, total_cost, reason)
    VALUES (v_item.restaurant_id, v_item.id, v_loc, v_lot, 'opening', v_item.stock,
            greatest(v_item.cost, 0), v_item.stock * greatest(v_item.cost, 0),
            'Saldo inicial migrado');

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: FUNCTION backfill_inventory_opening(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.backfill_inventory_opening() IS 'For every ingredient with stock <> 0 and no lot yet: creates the general lot at the default location (quantity = stock, unit_cost = cost) and one opening movement. Idempotent; returns the number of items backfilled.';


