--
-- Name: default_restaurant_id(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.default_restaurant_id() RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT CASE
    WHEN current_user = 'authenticated' THEN private.current_restaurant_id()
    WHEN current_user = 'postgres'
      THEN (SELECT r.id FROM public.restaurants r ORDER BY r.created_at, r.id LIMIT 1)
    ELSE NULL
  END
$$;


--
-- Name: FUNCTION default_restaurant_id(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.default_restaurant_id() IS 'Column default for the newly tenant-scoped tables. For `authenticated` it is the caller''s own tenant and NULL when the account has no profile (fail closed); for postgres (seed.sql and migrations) it is the oldest restaurant, ORDER BY created_at, id; for every other role (service_role webhooks, dashboard) it is NULL, so a write that omits restaurant_id fails NOT NULL instead of landing in an arbitrary tenant.';


--
-- Name: ensure_default_inventory_location(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ensure_default_inventory_location(p_restaurant_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid;
BEGIN
  SELECT l.id INTO v_id
    FROM public.inventory_locations l
   WHERE l.restaurant_id = p_restaurant_id AND l.is_default;

  IF v_id IS NULL THEN
    INSERT INTO public.inventory_locations (restaurant_id, name, code, is_default)
    VALUES (p_restaurant_id, 'Bodega principal',
            CASE WHEN EXISTS (SELECT 1 FROM public.inventory_locations l
                               WHERE l.restaurant_id = p_restaurant_id AND l.code = 'PRINCIPAL')
                 THEN 'PRINCIPAL-' || upper(substr(gen_random_uuid()::text, 1, 6))
                 ELSE 'PRINCIPAL' END,
            true)
    RETURNING id INTO v_id;
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: FUNCTION ensure_default_inventory_location(p_restaurant_id uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.ensure_default_inventory_location(p_restaurant_id uuid) IS 'Returns the default location of a restaurant, creating "Bodega principal" (code PRINCIPAL) when none exists.';


