-- Name: insert_default_payment_methods(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.insert_default_payment_methods(p_restaurant_id uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  INSERT INTO public.payment_methods (restaurant_id, code, name, kind, sort_order)
  VALUES
    (p_restaurant_id, 'cash',        'Efectivo',      'cash',       10),
    (p_restaurant_id, 'transfer',    'Transferencia', 'electronic', 20),
    (p_restaurant_id, 'nequi',       'Nequi',         'electronic', 30),
    (p_restaurant_id, 'bancolombia', 'Bancolombia',   'electronic', 40)
  ON CONFLICT (restaurant_id, code) DO NOTHING;
$$;


--
-- Name: FUNCTION insert_default_payment_methods(p_restaurant_id uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.insert_default_payment_methods(p_restaurant_id uuid) IS 'Installs the four default payment methods (Efectivo/Transferencia/Nequi/Bancolombia) for one restaurant. Idempotent (ON CONFLICT DO NOTHING). Called by public.seed_payment_methods_defaults() for new restaurants and by migration 20261006100000 for the ones that already exist.';


--
-- Name: inventory_average_cost(uuid, numeric, numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.inventory_average_cost(p_ingredient_id uuid, p_quantity numeric, p_unit_cost numeric) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  UPDATE public.ingredients i
     SET cost = CASE
                  WHEN greatest(i.stock, 0) + p_quantity <= 0 THEN p_unit_cost
                  ELSE (greatest(i.stock, 0) * COALESCE(i.cost, 0) + p_quantity * p_unit_cost)
                       / (greatest(i.stock, 0) + p_quantity)
                END
   WHERE i.id = p_ingredient_id
$$;


--
-- Name: FUNCTION inventory_average_cost(p_ingredient_id uuid, p_quantity numeric, p_unit_cost numeric); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.inventory_average_cost(p_ingredient_id uuid, p_quantity numeric, p_unit_cost numeric) IS 'Moving weighted-average cost: (max(stock, 0) * cost + quantity * unit_cost) / (max(stock, 0) + quantity). Call before the inbound quantity is added to stock.';


--
-- Name: inventory_caller(text, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.inventory_caller(p_fn text, p_roles text[], OUT profile_id uuid, OUT restaurant_id uuid, OUT app_role text) RETURNS record
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  SELECT p.id, p.restaurant_id, p.role INTO profile_id, restaurant_id, app_role
    FROM public.profiles p
   WHERE p.auth_user_id = auth.uid()
   LIMIT 1;

  IF profile_id IS NULL THEN
    RAISE EXCEPTION '%: the caller has no profile', p_fn USING ERRCODE = '42501';
  END IF;
  IF NOT (app_role = ANY (p_roles)) THEN
    RAISE EXCEPTION '%: role % may not call this function', p_fn, app_role USING ERRCODE = '42501';
  END IF;
END;
$$;


