-- Name: FUNCTION inventory_caller(p_fn text, p_roles text[], OUT profile_id uuid, OUT restaurant_id uuid, OUT app_role text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.inventory_caller(p_fn text, p_roles text[], OUT profile_id uuid, OUT restaurant_id uuid, OUT app_role text) IS 'Resolves the caller profile / tenant / role from auth.uid() and raises 42501 when there is no profile or the role is not in p_roles.';


