-- Name: FUNCTION inventory_control_enabled(p_restaurant_id uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.inventory_control_enabled(p_restaurant_id uuid) IS 'business_config inventory_control_enabled = ''true'' for the restaurant (missing key = disabled).';


--
-- Name: inventory_location(text, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.inventory_location(p_fn text, p_restaurant_id uuid, p_location_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF p_location_id IS NULL THEN
    RETURN private.ensure_default_inventory_location(p_restaurant_id);
  END IF;

  SELECT l.id INTO v_id
    FROM public.inventory_locations l
   WHERE l.id = p_location_id AND l.restaurant_id = p_restaurant_id AND l.is_active;

  IF v_id IS NULL THEN
    RAISE EXCEPTION '%: location % not found', p_fn, p_location_id USING ERRCODE = 'P0002';
  END IF;
  RETURN v_id;
END;
$$;


--
-- Name: FUNCTION inventory_location(p_fn text, p_restaurant_id uuid, p_location_id uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.inventory_location(p_fn text, p_restaurant_id uuid, p_location_id uuid) IS 'Returns p_location_id when it is an active location of the tenant (else P0002), or the default location when NULL.';


--
-- Name: inventory_put(uuid, uuid, uuid, numeric, numeric, text, date, timestamp with time zone, text, text, uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.inventory_put(p_restaurant_id uuid, p_ingredient_id uuid, p_location_id uuid, p_quantity numeric, p_unit_cost numeric, p_lot_code text, p_expires_on date, p_received_at timestamp with time zone, p_type text, p_ref_type text, p_ref_id uuid, p_by uuid, p_reason text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_code text := NULLIF(btrim(p_lot_code), '');
  v_cost numeric := greatest(COALESCE(p_unit_cost, 0), 0);
  v_lot  public.inventory_lots%ROWTYPE;
BEGIN
  SELECT * INTO v_lot
    FROM public.inventory_lots l
   WHERE l.ingredient_id = p_ingredient_id AND l.location_id = p_location_id
     AND l.lot_code IS NOT DISTINCT FROM v_code AND l.expires_on IS NOT DISTINCT FROM p_expires_on
   ORDER BY l.received_at
   LIMIT 1
   FOR UPDATE;

  IF v_lot.id IS NULL THEN
    INSERT INTO public.inventory_lots
      (restaurant_id, ingredient_id, location_id, lot_code, expires_on, quantity, unit_cost, received_at)
    VALUES (p_restaurant_id, p_ingredient_id, p_location_id, v_code, p_expires_on, p_quantity, v_cost,
            COALESCE(p_received_at, now()))
    RETURNING * INTO v_lot;
  ELSE
    UPDATE public.inventory_lots
       SET unit_cost = CASE WHEN quantity > 0 THEN (quantity * unit_cost + p_quantity * v_cost) / (quantity + p_quantity)
                            ELSE v_cost END,
           quantity = quantity + p_quantity
     WHERE id = v_lot.id;
  END IF;

  INSERT INTO public.inventory_movements
    (restaurant_id, ingredient_id, location_id, lot_id, movement_type, quantity, unit_cost,
     total_cost, reason, notes, reference_type, reference_id, created_by)
  VALUES (p_restaurant_id, p_ingredient_id, p_location_id, v_lot.id, p_type, p_quantity, v_cost,
          p_quantity * v_cost, p_reason, p_notes, p_ref_type, p_ref_id, p_by);

  RETURN v_lot.id;
END;
$$;


--
-- Name: FUNCTION inventory_put(p_restaurant_id uuid, p_ingredient_id uuid, p_location_id uuid, p_quantity numeric, p_unit_cost numeric, p_lot_code text, p_expires_on date, p_received_at timestamp with time zone, p_type text, p_ref_type text, p_ref_id uuid, p_by uuid, p_reason text, p_notes text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.inventory_put(p_restaurant_id uuid, p_ingredient_id uuid, p_location_id uuid, p_quantity numeric, p_unit_cost numeric, p_lot_code text, p_expires_on date, p_received_at timestamp with time zone, p_type text, p_ref_type text, p_ref_id uuid, p_by uuid, p_reason text, p_notes text) IS 'Adds p_quantity (> 0) to the matching lot (general when no code and no expiry), blending its unit cost, and writes one inbound movement. Returns the lot id.';


--
-- Name: inventory_sync_stock(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.inventory_sync_stock(p_ingredient_id uuid) RETURNS numeric
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  UPDATE public.ingredients i
     SET stock = COALESCE((SELECT sum(l.quantity) FROM public.inventory_lots l WHERE l.ingredient_id = i.id), 0)
   WHERE i.id = p_ingredient_id
  RETURNING i.stock
$$;


--
-- Name: FUNCTION inventory_sync_stock(p_ingredient_id uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.inventory_sync_stock(p_ingredient_id uuid) IS 'Sets ingredients.stock = sum(inventory_lots.quantity) for one item and returns it.';


--
-- Name: inventory_take(uuid, uuid, uuid, numeric, text, text, uuid, uuid, boolean, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.inventory_take(p_restaurant_id uuid, p_ingredient_id uuid, p_location_id uuid, p_quantity numeric, p_type text, p_ref_type text, p_ref_id uuid, p_by uuid, p_allow_negative boolean, p_reason text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_left     numeric := p_quantity;
  v_take     numeric;
  v_total    numeric := 0;
  v_portions jsonb := '[]'::jsonb;
  v_lot      record;
  v_general  public.inventory_lots%ROWTYPE;
  v_item     public.ingredients%ROWTYPE;
BEGIN
  FOR v_lot IN
    SELECT l.* FROM public.inventory_lots l
     WHERE l.ingredient_id = p_ingredient_id AND l.location_id = p_location_id AND l.quantity > 0
     ORDER BY l.expires_on ASC NULLS LAST, l.received_at, l.id
     FOR UPDATE
  LOOP
    EXIT WHEN v_left <= 0;
    v_take := least(v_lot.quantity, v_left);
    UPDATE public.inventory_lots SET quantity = quantity - v_take WHERE id = v_lot.id;
    INSERT INTO public.inventory_movements
      (restaurant_id, ingredient_id, location_id, lot_id, movement_type, quantity, unit_cost,
       total_cost, reason, notes, reference_type, reference_id, created_by)
    VALUES (p_restaurant_id, p_ingredient_id, p_location_id, v_lot.id, p_type, -v_take, v_lot.unit_cost,
            -v_take * v_lot.unit_cost, p_reason, p_notes, p_ref_type, p_ref_id, p_by);
    v_total := v_total + v_take * v_lot.unit_cost;
    v_portions := v_portions || jsonb_build_object(
      'lot_id', v_lot.id, 'lot_code', v_lot.lot_code, 'expires_on', v_lot.expires_on,
      'received_at', v_lot.received_at, 'quantity', v_take, 'unit_cost', v_lot.unit_cost);
    v_left := v_left - v_take;
  END LOOP;

  IF v_left > 0 THEN
    SELECT * INTO v_item FROM public.ingredients i WHERE i.id = p_ingredient_id;
    IF NOT p_allow_negative THEN
      RAISE EXCEPTION 'insufficient stock: % (missing % %)', v_item.name, v_left::numeric(14,3), v_item.unit
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('ingredient_id', p_ingredient_id, 'missing', v_left)::text;
    END IF;

    INSERT INTO public.inventory_lots (restaurant_id, ingredient_id, location_id, quantity, unit_cost)
    VALUES (p_restaurant_id, p_ingredient_id, p_location_id, 0, greatest(COALESCE(v_item.cost, 0), 0))
    ON CONFLICT (ingredient_id, location_id) WHERE lot_code IS NULL AND expires_on IS NULL DO NOTHING;

    SELECT * INTO v_general FROM public.inventory_lots l
     WHERE l.ingredient_id = p_ingredient_id AND l.location_id = p_location_id
       AND l.lot_code IS NULL AND l.expires_on IS NULL
     FOR UPDATE;

    UPDATE public.inventory_lots SET quantity = quantity - v_left WHERE id = v_general.id;
    INSERT INTO public.inventory_movements
      (restaurant_id, ingredient_id, location_id, lot_id, movement_type, quantity, unit_cost,
       total_cost, reason, notes, reference_type, reference_id, created_by)
    VALUES (p_restaurant_id, p_ingredient_id, p_location_id, v_general.id, p_type, -v_left,
            COALESCE(v_item.cost, 0), -v_left * COALESCE(v_item.cost, 0), p_reason, p_notes,
            p_ref_type, p_ref_id, p_by);
    v_total := v_total + v_left * COALESCE(v_item.cost, 0);
  END IF;

  RETURN jsonb_build_object('total_cost', v_total,
                            'missing', CASE WHEN v_left > 0 THEN v_left ELSE 0 END,
                            'portions', v_portions);
END;
$$;


--
-- Name: FUNCTION inventory_take(p_restaurant_id uuid, p_ingredient_id uuid, p_location_id uuid, p_quantity numeric, p_type text, p_ref_type text, p_ref_id uuid, p_by uuid, p_allow_negative boolean, p_reason text, p_notes text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.inventory_take(p_restaurant_id uuid, p_ingredient_id uuid, p_location_id uuid, p_quantity numeric, p_type text, p_ref_type text, p_ref_id uuid, p_by uuid, p_allow_negative boolean, p_reason text, p_notes text) IS 'Removes p_quantity (> 0) FEFO from the positive lots of an item at a location, writing one outbound movement per lot. Shortage: general lot goes negative when p_allow_negative, else P0001. Returns {total_cost, missing, portions[]}.';


--
-- Name: next_inventory_counter(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.next_inventory_counter(p_restaurant_id uuid, p_counter text) RETURNS bigint
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  INSERT INTO private.inventory_counters AS c (restaurant_id, counter, value)
  VALUES (p_restaurant_id, p_counter, 1)
  ON CONFLICT (restaurant_id, counter) DO UPDATE SET value = c.value + 1
  RETURNING c.value
$$;


--
-- Name: FUNCTION next_inventory_counter(p_restaurant_id uuid, p_counter text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.next_inventory_counter(p_restaurant_id uuid, p_counter text) IS 'Returns the next value of a per-restaurant counter (1-based), row-locked through the upsert.';


--
-- Name: recompute_order_bill(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.recompute_order_bill(p_order_id uuid) RETURNS TABLE(subtotal numeric, tax numeric, tip numeric, total numeric, tax_percentage numeric, tip_percentage numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_subtotal  bigint := 0;
  v_tax_pct   numeric := 0;
  v_tip_pct   numeric := 0;
  v_tax       bigint := 0;
  v_tip       bigint := 0;
  v_total     bigint := 0;
BEGIN
  SELECT coalesce(sum(round(oi.price * oi.quantity)), 0)::bigint
    INTO v_subtotal
    FROM public.order_items oi
   WHERE oi.order_id = p_order_id;

  SELECT coalesce(o.tax_percentage, 0), coalesce(o.tip_percentage, 0)
    INTO v_tax_pct, v_tip_pct
    FROM public.orders o
   WHERE o.id = p_order_id;

  v_tax   := round((v_subtotal * v_tax_pct / 100)::numeric)::bigint;
  v_tip   := round((v_subtotal * v_tip_pct / 100)::numeric)::bigint;
  v_total := v_subtotal + v_tax + v_tip;

  UPDATE public.orders o
     SET subtotal = v_subtotal,
         tax      = v_tax,
         tip      = v_tip,
         total    = v_total,
         updated_at = now()
   WHERE o.id = p_order_id;

  RETURN QUERY SELECT v_subtotal::numeric, v_tax::numeric, v_tip::numeric,
                      v_total::numeric, v_tax_pct, v_tip_pct;
END;
$$;


--
-- Name: FUNCTION recompute_order_bill(p_order_id uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.recompute_order_bill(p_order_id uuid) IS 'Private bill recompute helper used by split_order and undo_split. SECURITY DEFINER (owner postgres). Reads order_items regardless of RLS, writes the new subtotal/tax/tip/total/updated_at on the order. Tip is suggested from tip_percentage (same as pay_order). Not exposed to PostgREST.';


--
-- Name: apply_inventory_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_inventory_count(p_count_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  c_fn constant text := 'apply_inventory_count';
  v_caller   record;
  v_count    public.inventory_counts%ROWTYPE;
  v_line     record;
  v_current  numeric;
  v_diff     numeric;
  v_cost     numeric;
  v_adjusted integer := 0;
  v_delta    numeric := 0;
BEGIN
  SELECT * INTO v_caller FROM private.inventory_caller(c_fn, ARRAY['admin']);

  SELECT * INTO v_count FROM public.inventory_counts c
   WHERE c.id = p_count_id AND c.restaurant_id = v_caller.restaurant_id
   FOR UPDATE;
  IF v_count.id IS NULL THEN
    RAISE EXCEPTION '%: count % not found', c_fn, p_count_id USING ERRCODE = 'P0002';
  END IF;
  IF v_count.status <> 'open' THEN
    RAISE EXCEPTION '%: count % is %', c_fn, v_count.number, v_count.status USING ERRCODE = 'P0001';
  END IF;

  FOR v_line IN
    SELECT cl.ingredient_id, cl.counted_quantity, i.cost
      FROM public.inventory_count_lines cl
      JOIN public.ingredients i ON i.id = cl.ingredient_id
     WHERE cl.count_id = v_count.id AND cl.counted_quantity IS NOT NULL
     ORDER BY cl.ingredient_id
     FOR UPDATE OF i
  LOOP
    SELECT COALESCE(sum(l.quantity), 0) INTO v_current
      FROM public.inventory_lots l
     WHERE l.ingredient_id = v_line.ingredient_id AND l.location_id = v_count.location_id;
    v_diff := v_line.counted_quantity - v_current;
    CONTINUE WHEN v_diff = 0;

    IF v_diff > 0 THEN
      v_cost := COALESCE(v_line.cost, 0);
      PERFORM private.inventory_put(v_caller.restaurant_id, v_line.ingredient_id, v_count.location_id, v_diff,
                                    v_cost, NULL, NULL, now(), 'count_adjustment',
                                    'inventory_count', v_count.id, v_caller.profile_id, NULL, NULL);
      v_delta := v_delta + v_diff * v_cost;
    ELSE
      v_delta := v_delta - (private.inventory_take(v_caller.restaurant_id, v_line.ingredient_id, v_count.location_id,
                                                   -v_diff, 'count_adjustment', 'inventory_count', v_count.id,
                                                   v_caller.profile_id, false, NULL, NULL)->>'total_cost')::numeric;
    END IF;
    PERFORM private.inventory_sync_stock(v_line.ingredient_id);
    v_adjusted := v_adjusted + 1;
  END LOOP;

  UPDATE public.inventory_counts SET status = 'applied', applied_at = now() WHERE id = v_count.id;

  RETURN jsonb_build_object(
    'count_id', v_count.id,
    'status', 'applied',
    'adjusted_lines', v_adjusted,
    'value_delta', round(v_delta, 4)
  );
END;
$$;


--
-- Name: FUNCTION apply_inventory_count(p_count_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_inventory_count(p_count_id uuid) IS 'Applies an open count (admin): for every line with counted_quantity, writes count_adjustment movements so the location balance equals counted_quantity (surplus to the general lot at ingredients.cost, deficit FEFO). Lines left NULL are skipped. Marks the count applied (P0001 when not open). Returns {count_id, status, adjusted_lines, value_delta}.';


--
-- Name: check_dishes_stock(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_dishes_stock(p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  c_fn constant text := 'check_dishes_stock';
  v_caller    record;
  v_loc       uuid;
  v_item      jsonb;
  v_dish      uuid;
  v_qty       integer;
  v_shortages jsonb;
BEGIN
  SELECT * INTO v_caller FROM private.inventory_caller(c_fn,
    ARRAY['admin', 'cashier', 'waiter', 'kitchen', 'delivery_operator']);

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) > 100 THEN
    RAISE EXCEPTION '%: p_items must be an array of at most 100 items', c_fn USING ERRCODE = '22023';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    BEGIN
      v_dish := (v_item->>'dish_id')::uuid;
      v_qty := (v_item->>'quantity')::integer;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION '%: each item needs a uuid dish_id and an integer quantity', c_fn USING ERRCODE = '22023';
    END;
    IF v_dish IS NULL OR v_qty IS NULL OR v_qty NOT BETWEEN 1 AND 999 THEN
      RAISE EXCEPTION '%: each item needs dish_id and quantity 1..999', c_fn USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.dishes d WHERE d.id = v_dish AND d.restaurant_id = v_caller.restaurant_id) THEN
      RAISE EXCEPTION '%: dish % not found', c_fn, v_dish USING ERRCODE = 'P0002';
    END IF;
  END LOOP;

  IF NOT private.inventory_control_enabled(v_caller.restaurant_id) THEN
    RETURN jsonb_build_object('ok', true, 'enabled', false, 'shortages', '[]'::jsonb);
  END IF;

  v_loc := private.ensure_default_inventory_location(v_caller.restaurant_id);

  SELECT jsonb_agg(jsonb_build_object(
           'ingredient_id', q.ingredient_id, 'name', q.name, 'unit', q.unit,
           'required', q.required, 'available', q.available,
           'missing', (q.required - q.available)::numeric(14,3)) ORDER BY q.name)
    INTO v_shortages
    FROM (
      SELECT i.id AS ingredient_id, i.name, i.unit,
             sum(ri.quantity * x.quantity / r.yield_quantity)::numeric(14,3) AS required,
             greatest(COALESCE((SELECT sum(l.quantity) FROM public.inventory_lots l
                                 WHERE l.ingredient_id = i.id AND l.location_id = v_loc), 0), 0)::numeric(14,3) AS available
        FROM jsonb_to_recordset(p_items) AS x(dish_id uuid, quantity integer)
        JOIN public.recipes r ON r.dish_id = x.dish_id
        JOIN public.recipe_ingredients ri ON ri.recipe_id = r.id
        JOIN public.ingredients i ON i.id = ri.ingredient_id
       GROUP BY i.id, i.name, i.unit
    ) q
   WHERE q.required > q.available;

  RETURN jsonb_build_object('ok', v_shortages IS NULL, 'enabled', true,
                            'shortages', COALESCE(v_shortages, '[]'::jsonb));
END;
$$;


--
-- Name: FUNCTION check_dishes_stock(p_items jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_dishes_stock(p_items jsonb) IS 'Pre-send stock check for a cart (any tenant role). p_items = [{dish_id, quantity 1..999}] (<= 100). Aggregates the dish formulas and compares against the default-location balance (negative counts as 0). Writes nothing. Returns {ok, enabled, shortages:[{ingredient_id, name, unit, required, available, missing}]}; enabled = false (ok = true, no shortages) when inventory control is off.';


--
-- Name: close_register(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_register(p_cash_register_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_caller_tenant   uuid;
  v_caller_role     text;

  v_register        public.cash_registers%ROWTYPE;
  v_summary         jsonb;
  v_final_cash      bigint;
BEGIN
  -- 1. Caller resolution.
  v_caller_tenant := private.current_restaurant_id();
  v_caller_role   := private.current_app_role();

  IF v_caller_tenant IS NULL OR v_caller_role IS NULL THEN
    RAISE EXCEPTION 'close_register: the caller has no profile'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_caller_role NOT IN ('cashier', 'admin') THEN
    RAISE EXCEPTION 'close_register: only cashier or admin may close a register'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 2. Lock the register row FOR UPDATE. The same row pay_order takes FOR SHARE;
  -- a concurrent close_register / pay_order pair serialize on this row, not on
  -- any order row.
  SELECT cr.* INTO v_register
    FROM public.cash_registers cr
   WHERE cr.id = p_cash_register_id
     FOR UPDATE;

  IF NOT FOUND OR v_register.restaurant_id <> v_caller_tenant THEN
    RAISE EXCEPTION 'close_register: cash register % not found', p_cash_register_id
      USING ERRCODE = 'P0002';
  END IF;

  -- The summary is computed at the lock instant: it is the snapshot the close
  -- dialog renders, and is what pay_order / register_summary would see if they
  -- ran right after the close.
  v_summary := public.register_summary(ARRAY[p_cash_register_id]::uuid[]);

  IF v_register.status = 'closed' THEN
    -- 3. Already-closed replay. No writes; closing_timestamp and final_cash are
    -- the stored values from the original close.
    RETURN jsonb_build_object(
      'status',            'already_closed',
      'cash_register_id',  v_register.id,
      'closing_timestamp', v_register.closing_timestamp,
      'final_cash',        coalesce(round(v_register.final_cash)::bigint, 0),
      'summary',           v_summary
    );
  END IF;

  -- 4. Happy path: close the drawer.
  v_final_cash := (v_summary ->> 'expected_cash_after_tips')::bigint;

  UPDATE public.cash_registers cr
     SET status            = 'closed',
         closing_timestamp = now(),
         final_cash        = v_final_cash,
         updated_at        = now()
   WHERE cr.id = p_cash_register_id;

  RETURN jsonb_build_object(
    'status',           'closed',
    'cash_register_id', v_register.id,
    'final_cash',       v_final_cash,
    'summary',          v_summary
  );
END;
$$;


--
-- Name: FUNCTION close_register(p_cash_register_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.close_register(p_cash_register_id uuid) IS 'Closes one cash register. SECURITY DEFINER (owner postgres). Caller resolution through private.current_restaurant_id() / private.current_app_role() (42501 for non-cashier/admin). Locks the register row FOR UPDATE so it serializes with pay_order (FOR SHARE on the same row) - the deadlock cycle would need a lock the other way around, which neither function takes. P0002 if the row is missing or belongs to another tenant. If status=''closed'' when the lock lands, returns {status:''already_closed'', cash_register_id, closing_timestamp, final_cash, summary} with no writes (idempotent replay). Otherwise computes the summary with public.register_summary, UPDATEs the register (status=''closed'', closing_timestamp=now(), final_cash=expected_cash_after_tips, updated_at=now()) and returns {status:''closed'', cash_register_id, final_cash, summary}. The ''closed'' status value is the same one the existing schema already uses; pay_order already rejects it with P0001, pinned on the round-trip by 090.';


--
-- Name: consume_order_stock(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_order_stock(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  c_fn constant text := 'consume_order_stock';
  v_caller    record;
  v_loc       uuid;
  v_item      record;
  v_line      record;
  v_taken     jsonb;
  v_items     integer := 0;
  v_total     numeric := 0;
  v_shortages jsonb := '[]'::jsonb;
  v_touched   uuid[] := '{}';
  v_id        uuid;
BEGIN
  SELECT * INTO v_caller FROM private.inventory_caller(c_fn, ARRAY['admin', 'cashier', 'waiter', 'delivery_operator']);

  IF NOT EXISTS (SELECT 1 FROM public.orders o WHERE o.id = p_order_id AND o.restaurant_id = v_caller.restaurant_id) THEN
    RAISE EXCEPTION '%: order % not found', c_fn, p_order_id USING ERRCODE = 'P0002';
  END IF;

  IF NOT private.inventory_control_enabled(v_caller.restaurant_id) THEN
    RETURN jsonb_build_object('order_id', p_order_id, 'enabled', false, 'consumed_items', 0,
                              'total_cost', 0, 'shortages', '[]'::jsonb);
  END IF;

  v_loc := private.ensure_default_inventory_location(v_caller.restaurant_id);

  -- Lock every ingredient this order can touch up front, in id order, so two
  -- orders sharing ingredients always queue instead of deadlocking.
  PERFORM 1 FROM public.ingredients i
   WHERE i.id IN (
     SELECT ri.ingredient_id
       FROM public.order_items oi
       JOIN public.recipes r ON r.dish_id = oi.dish_id
       JOIN public.recipe_ingredients ri ON ri.recipe_id = r.id
      WHERE oi.order_id = p_order_id
        AND oi.restaurant_id = v_caller.restaurant_id
        AND oi.stock_consumed_at IS NULL)
   ORDER BY i.id
   FOR UPDATE;

  FOR v_item IN
    SELECT oi.id, oi.dish_id, oi.quantity
      FROM public.order_items oi
     WHERE oi.order_id = p_order_id
       AND oi.restaurant_id = v_caller.restaurant_id
       AND oi.stock_consumed_at IS NULL
       AND COALESCE(oi.status, '') <> 'cancelled'
     ORDER BY oi.id
     FOR UPDATE
  LOOP
    FOR v_line IN
      SELECT ri.ingredient_id, (ri.quantity * v_item.quantity / r.yield_quantity)::numeric(14,3) AS required
        FROM public.recipes r
        JOIN public.recipe_ingredients ri ON ri.recipe_id = r.id
       WHERE r.dish_id = v_item.dish_id
       ORDER BY ri.ingredient_id
    LOOP
      CONTINUE WHEN v_line.required <= 0;
      PERFORM 1 FROM public.ingredients i WHERE i.id = v_line.ingredient_id FOR UPDATE;
      v_taken := private.inventory_take(v_caller.restaurant_id, v_line.ingredient_id, v_loc, v_line.required,
                                        'sale', 'order_item', v_item.id, v_caller.profile_id, true, NULL, NULL);
      v_total := v_total + (v_taken->>'total_cost')::numeric;
      IF (v_taken->>'missing')::numeric > 0 THEN
        v_shortages := v_shortages || jsonb_build_object(
          'ingredient_id', v_line.ingredient_id,
          'name', (SELECT i.name FROM public.ingredients i WHERE i.id = v_line.ingredient_id),
          'unit', (SELECT i.unit FROM public.ingredients i WHERE i.id = v_line.ingredient_id),
          'missing', ((v_taken->>'missing')::numeric)::numeric(14,3));
      END IF;
      IF NOT v_line.ingredient_id = ANY (v_touched) THEN
        v_touched := v_touched || v_line.ingredient_id;
      END IF;
    END LOOP;

    UPDATE public.order_items SET stock_consumed_at = now() WHERE id = v_item.id;
    v_items := v_items + 1;
  END LOOP;

  FOREACH v_id IN ARRAY v_touched LOOP
    PERFORM private.inventory_sync_stock(v_id);
  END LOOP;

  RETURN jsonb_build_object('order_id', p_order_id, 'enabled', true, 'consumed_items', v_items,
                            'total_cost', round(v_total, 4), 'shortages', v_shortages);
END;
$$;


--
-- Name: FUNCTION consume_order_stock(p_order_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.consume_order_stock(p_order_id uuid) IS 'Deducts the dish formulas of an order''s not-yet-consumed, non-cancelled items from the default location (admin, cashier, waiter, delivery_operator). Reads order_items server-side; each item is stamped stock_consumed_at so repeated calls are idempotent. FEFO by expires_on then received_at; a shortage drives the general lot negative and is reported. No-op when business_config inventory_control_enabled is not ''true''. Returns {order_id, enabled, consumed_items, total_cost, shortages:[{ingredient_id, name, unit, missing}]}.';


--
-- Name: create_delivery_order(jsonb, jsonb, jsonb, bigint, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_delivery_order(p_customer jsonb, p_address jsonb, p_items jsonb, p_delivery_fee bigint, p_payment_mode text, p_cash_change_for bigint DEFAULT NULL::bigint, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_caller_tenant   uuid;
  v_caller_role     text;
  v_caller_profile  uuid;

  v_customer_id     uuid;
  v_customer_name   text;
  v_customer_phone  text;
  v_address_id      uuid := NULL;
  v_addr_customer_id uuid;
  v_address_line    text;
  v_address_neigh   text;
  v_address_ref     text;
  v_address_label   text;

  v_items_count     integer;
  v_item            jsonb;
  v_line_no         integer;
  v_dish_id         uuid;
  v_dish_qty        integer;
  v_dish_comments   text;

  v_distinct_dishes uuid[] := '{}'::uuid[];

  v_subtotal        bigint := 0;
  v_tax_pct         numeric := 0;
  v_tax             bigint := 0;
  v_total           bigint := 0;

  v_order_id        uuid;
  v_fee             bigint;
  v_change          bigint;

  v_now             timestamptz := now();
BEGIN
  -- 1. Caller resolution.
  v_caller_tenant := private.current_restaurant_id();
  v_caller_role   := private.current_app_role();

  IF v_caller_tenant IS NULL OR v_caller_role IS NULL THEN
    RAISE EXCEPTION 'create_delivery_order: the caller has no profile'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_caller_role NOT IN ('admin', 'delivery_operator') THEN
    RAISE EXCEPTION 'create_delivery_order: only admin or delivery_operator may take a delivery order'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT p.id INTO v_caller_profile
    FROM public.profiles p
   WHERE p.auth_user_id = auth.uid()
   LIMIT 1;

  IF v_caller_profile IS NULL THEN
    RAISE EXCEPTION 'create_delivery_order: the caller has no profile'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 2. Input validation.
  IF p_customer IS NULL OR jsonb_typeof(p_customer) <> 'object' THEN
    RAISE EXCEPTION 'create_delivery_order: p_customer must be a JSON object'
      USING ERRCODE = '22023';
  END IF;

  IF p_address IS NULL OR jsonb_typeof(p_address) <> 'object' THEN
    RAISE EXCEPTION 'create_delivery_order: p_address must be a JSON object'
      USING ERRCODE = '22023';
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'create_delivery_order: p_items must be a JSON array'
      USING ERRCODE = '22023';
  END IF;

  v_items_count := jsonb_array_length(p_items);
  IF v_items_count = 0 THEN
    RAISE EXCEPTION 'create_delivery_order: p_items must be a non-empty array'
      USING ERRCODE = '22023';
  END IF;

  IF v_items_count > 100 THEN
    RAISE EXCEPTION 'create_delivery_order: p_items accepts at most 100 lines'
      USING ERRCODE = '22023';
  END IF;

  IF p_delivery_fee IS NULL OR p_delivery_fee < 0 THEN
    RAISE EXCEPTION 'create_delivery_order: p_delivery_fee must be a non-negative integer'
      USING ERRCODE = '22023';
  END IF;

  IF char_length(btrim(coalesce(p_notes, ''))) > 300 THEN
    RAISE EXCEPTION 'create_delivery_order: p_notes accepts at most 300 characters'
      USING ERRCODE = '22023';
  END IF;

  IF p_payment_mode IS NULL OR p_payment_mode NOT IN ('prepaid', 'cash_on_delivery') THEN
    RAISE EXCEPTION 'create_delivery_order: p_payment_mode must be ''prepaid'' or ''cash_on_delivery'''
      USING ERRCODE = '22023';
  END IF;

  IF p_payment_mode = 'cash_on_delivery' THEN
    IF p_cash_change_for IS NOT NULL AND p_cash_change_for < 0 THEN
      RAISE EXCEPTION 'create_delivery_order: p_cash_change_for must be a non-negative integer (or NULL)'
        USING ERRCODE = '22023';
    END IF;
  ELSE
    IF p_cash_change_for IS NOT NULL THEN
      RAISE EXCEPTION 'create_delivery_order: p_cash_change_for must be NULL when p_payment_mode = ''prepaid'''
        USING ERRCODE = '22023';
    END IF;
  END IF;

  -- 3. Customer.
  IF (p_customer ? 'id') AND (p_customer ? 'phone') THEN
    RAISE EXCEPTION 'create_delivery_order: p_customer must carry either id or phone, not both'
      USING ERRCODE = '22023';
  END IF;

  IF NOT (p_customer ? 'id') AND NOT (p_customer ? 'phone') THEN
    RAISE EXCEPTION 'create_delivery_order: p_customer must carry id or phone'
      USING ERRCODE = '22023';
  END IF;

  IF p_customer ? 'id' THEN
    BEGIN
      v_customer_id := (p_customer ->> 'id')::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'create_delivery_order: p_customer.id is not a uuid'
        USING ERRCODE = '22023';
    END;

    SELECT c.id, c.name, c.phone
      INTO v_customer_id, v_customer_name, v_customer_phone
      FROM public.customers c
     WHERE c.id = v_customer_id
       AND c.restaurant_id = v_caller_tenant;

    IF v_customer_id IS NULL THEN
      RAISE EXCEPTION 'create_delivery_order: customer % not found', (p_customer ->> 'id')
        USING ERRCODE = 'P0002';
    END IF;
  ELSE
    -- p_customer ? 'phone' (guaranteed by the xor above)
    v_customer_phone := btrim(coalesce(p_customer ->> 'phone', ''));
    IF v_customer_phone !~ '^[0-9]{7,15}$' THEN
      RAISE EXCEPTION 'create_delivery_order: p_customer.phone must match 7..15 digits'
        USING ERRCODE = '22023';
    END IF;

    SELECT c.id, c.name, c.phone
      INTO v_customer_id, v_customer_name, v_customer_phone
      FROM public.customers c
     WHERE c.phone = v_customer_phone
       AND c.restaurant_id = v_caller_tenant;

    IF v_customer_id IS NULL THEN
      -- New customer: name is required. Use the request's name, not its
      -- phone (the previous version of this block had a copy-paste that
      -- assigned the phone to the name variable).
      v_customer_name := btrim(coalesce(p_customer ->> 'name', ''));
      IF v_customer_name = '' OR length(v_customer_name) > 120 THEN
        RAISE EXCEPTION 'create_delivery_order: p_customer.name is required when creating a new customer (1..120 chars)'
          USING ERRCODE = '22023';
      END IF;

      -- v_customer_phone was overwritten by the zero-rows INTO above; re-set
      -- it from the request so the INSERT has the right value.
      v_customer_phone := btrim(p_customer ->> 'phone');

      INSERT INTO public.customers (restaurant_id, phone, name)
      VALUES (v_caller_tenant, v_customer_phone, v_customer_name)
      RETURNING id, name, phone
        INTO v_customer_id, v_customer_name, v_customer_phone;
    ELSE
      -- Existing customer: update name only when the request carries a
      -- different value (btrim-collapsed, length 1..120).
      DECLARE
        v_requested_name text := btrim(coalesce(p_customer ->> 'name', ''));
      BEGIN
        IF v_requested_name <> '' AND length(v_requested_name) <= 120
           AND v_requested_name IS DISTINCT FROM v_customer_name THEN
          UPDATE public.customers c
             SET name = v_requested_name
           WHERE c.id = v_customer_id;
          v_customer_name := v_requested_name;
        END IF;
      END;
    END IF;
  END IF;

  -- 4. Address.
  IF (p_address ? 'id') AND (p_address ? 'address_line') THEN
    RAISE EXCEPTION 'create_delivery_order: p_address must carry either id or address_line, not both'
      USING ERRCODE = '22023';
  END IF;

  IF p_address ? 'id' THEN
    BEGIN
      v_address_id := (p_address ->> 'id')::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'create_delivery_order: p_address.id is not a uuid'
        USING ERRCODE = '22023';
    END;

    SELECT a.id, a.customer_id, a.address_line, a.neighborhood, a.reference, a.label
      INTO v_address_id, v_addr_customer_id, v_address_line, v_address_neigh, v_address_ref, v_address_label
      FROM public.customer_addresses a
     WHERE a.id = v_address_id
       AND a.restaurant_id = v_caller_tenant;

    IF v_address_id IS NULL THEN
      RAISE EXCEPTION 'create_delivery_order: address % not found', (p_address ->> 'id')
        USING ERRCODE = 'P0002';
    END IF;

    -- The address must belong to the customer we resolved above. Without
    -- this check, the address's customer_id could silently overwrite
    -- v_customer_id and the order would be billed/snapshotted against the
    -- wrong customer.
    IF v_addr_customer_id IS DISTINCT FROM v_customer_id THEN
      RAISE EXCEPTION 'create_delivery_order: address % does not belong to the resolved customer',
        v_address_id
        USING ERRCODE = 'P0002';
    END IF;
  ELSE
    v_address_line := btrim(coalesce(p_address ->> 'address_line', ''));
    IF v_address_line = '' OR length(v_address_line) > 200 THEN
      RAISE EXCEPTION 'create_delivery_order: p_address.address_line is required (1..200 chars)'
        USING ERRCODE = '22023';
    END IF;
    v_address_neigh := NULLIF(btrim(coalesce(p_address ->> 'neighborhood', '')), '');
    v_address_ref   := NULLIF(btrim(coalesce(p_address ->> 'reference',    '')), '');
    v_address_label := NULLIF(btrim(coalesce(p_address ->> 'label',        '')), '');

    IF v_address_neigh IS NOT NULL AND length(v_address_neigh) > 80 THEN
      RAISE EXCEPTION 'create_delivery_order: p_address.neighborhood must be <= 80 chars'
        USING ERRCODE = '22023';
    END IF;
    IF v_address_ref IS NOT NULL AND length(v_address_ref) > 200 THEN
      RAISE EXCEPTION 'create_delivery_order: p_address.reference must be <= 200 chars'
        USING ERRCODE = '22023';
    END IF;
    IF v_address_label IS NOT NULL AND length(v_address_label) > 40 THEN
      RAISE EXCEPTION 'create_delivery_order: p_address.label must be <= 40 chars'
        USING ERRCODE = '22023';
    END IF;

    IF coalesce((p_address ->> 'save')::boolean, false) THEN
      INSERT INTO public.customer_addresses (
        restaurant_id, customer_id, label, address_line, neighborhood, reference, is_default
      ) VALUES (
        v_caller_tenant, v_customer_id, v_address_label, v_address_line, v_address_neigh, v_address_ref, false
      )
      RETURNING id INTO v_address_id;
    END IF;
  END IF;

  -- 5. Items: collect distinct dish_ids, then resolve server-side.
  FOR v_line_no IN 1..v_items_count LOOP
    v_item := p_items -> (v_line_no - 1);

    IF v_item IS NULL OR jsonb_typeof(v_item) <> 'object' THEN
      RAISE EXCEPTION 'create_delivery_order: item[%] must be a JSON object', v_line_no
        USING ERRCODE = '22023';
    END IF;

    IF NOT (v_item ? 'dish_id') THEN
      RAISE EXCEPTION 'create_delivery_order: item[%] is missing dish_id', v_line_no
        USING ERRCODE = '22023';
    END IF;

    BEGIN
      v_dish_id := (v_item ->> 'dish_id')::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'create_delivery_order: item[%].dish_id is not a uuid', v_line_no
        USING ERRCODE = '22023';
    END;

    IF NOT (v_item ? 'quantity') THEN
      RAISE EXCEPTION 'create_delivery_order: item[%] is missing quantity', v_line_no
        USING ERRCODE = '22023';
    END IF;

    BEGIN
      v_dish_qty := (v_item ->> 'quantity')::integer;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'create_delivery_order: item[%].quantity is not an integer', v_line_no
        USING ERRCODE = '22023';
    END;

    IF v_dish_qty IS NULL OR v_dish_qty < 1 OR v_dish_qty > 999 THEN
      RAISE EXCEPTION 'create_delivery_order: item[%].quantity must be between 1 and 999', v_line_no
        USING ERRCODE = '22023';
    END IF;

    IF NOT (v_dish_id = ANY (v_distinct_dishes)) THEN
      v_distinct_dishes := v_distinct_dishes || v_dish_id;
    END IF;
  END LOOP;

  -- Server-side price/name resolution: every distinct dish_id must resolve to
  -- a row of the caller's tenant. The SELECT goes against public.dishes (RLS
  -- is bypassed by SECURITY DEFINER + owner postgres, but the tenant filter
  -- is the same one the policies apply for an authenticated caller).
  IF EXISTS (
    SELECT 1
      FROM unnest(v_distinct_dishes) AS d(dish_id)
     WHERE NOT EXISTS (
       SELECT 1 FROM public.dishes di
        WHERE di.id = d.dish_id
          AND di.restaurant_id = v_caller_tenant
     )
  ) THEN
    RAISE EXCEPTION 'create_delivery_order: one or more dish_id values do not resolve to a menu item of the caller tenant'
      USING ERRCODE = 'P0002';
  END IF;

  -- 6. Bill: subtotal / tax / total. tax_percentage comes from business_config.
  -- Server-side aggregation: per-dish quantity is the sum of all requested
  -- lines for that dish, then subtotal is sum(round(price * per_dish_qty)).
  -- Multiple lines for the same dish collapse into one row.
  SELECT coalesce(sum(round(di.price * coalesce(line_qty.q, 0))), 0)::bigint
    INTO v_subtotal
    FROM public.dishes di
    JOIN unnest(v_distinct_dishes) AS d(dish_id) ON d.dish_id = di.id
    JOIN LATERAL (
      SELECT sum((item ->> 'quantity')::integer) AS q
        FROM jsonb_array_elements(p_items) item
       WHERE (item ->> 'dish_id')::uuid = di.id
    ) AS line_qty ON true
   WHERE di.restaurant_id = v_caller_tenant;

  SELECT coalesce(nullif(bc.value, '')::numeric, 0)
    INTO v_tax_pct
    FROM public.business_config bc
   WHERE bc.restaurant_id = v_caller_tenant
     AND bc.key = 'tax_percentage'
   LIMIT 1;

  v_tax   := round((v_subtotal * coalesce(v_tax_pct, 0) / 100)::numeric)::bigint;
  v_total := v_subtotal + v_tax;

  -- 7. Order.
  INSERT INTO public.orders (
    restaurant_id, table_id, waiter_id, status,
    subtotal, tax, tax_percentage, tip, tip_percentage, total,
    total_discounts, is_partial_order, parent_order_id,
    order_type
  ) VALUES (
    v_caller_tenant, NULL, v_caller_profile, 'kitchen',
    v_subtotal, v_tax, coalesce(v_tax_pct, 0), 0, 0, v_total,
    0, false, NULL,
    'delivery'
  )
  RETURNING id INTO v_order_id;

  -- 8. order_items: one row per requested line, with name/price from the menu.
  FOR v_line_no IN 1..v_items_count LOOP
    v_item := p_items -> (v_line_no - 1);
    v_dish_id := (v_item ->> 'dish_id')::uuid;
    v_dish_qty := (v_item ->> 'quantity')::integer;
    v_dish_comments := NULLIF(btrim(coalesce(v_item ->> 'comments', '')), '');

    INSERT INTO public.order_items (
      order_id, dish_id, name, price, quantity, comments,
      status, added_at, restaurant_id
    )
    SELECT v_order_id, di.id, di.name, di.price, v_dish_qty, v_dish_comments,
           'kitchen', v_now, v_caller_tenant
      FROM public.dishes di
     WHERE di.id = v_dish_id
       AND di.restaurant_id = v_caller_tenant;
  END LOOP;

  -- 9. order_deliveries (1:1 mirror).
  v_fee   := p_delivery_fee;
  v_change := CASE WHEN p_payment_mode = 'cash_on_delivery' THEN p_cash_change_for
                   ELSE NULL END;

  INSERT INTO public.order_deliveries (
    order_id, restaurant_id, customer_id,
    customer_name, customer_phone,
    address_line, neighborhood, address_reference,
    delivery_fee, payment_mode, cash_change_for,
    delivery_status, notes
  ) VALUES (
    v_order_id, v_caller_tenant, v_customer_id,
    v_customer_name, v_customer_phone,
    v_address_line, v_address_neigh, v_address_ref,
    v_fee, p_payment_mode, v_change,
    'received', nullif(btrim(coalesce(p_notes, '')), '')
  );

  RETURN jsonb_build_object(
    'order_id',    v_order_id,
    'customer_id', v_customer_id,
    'address_id',  v_address_id,
    'delivery', (
      SELECT to_jsonb(od)
        FROM public.order_deliveries od
       WHERE od.order_id = v_order_id
    )
  );
END;
$_$;


--
-- Name: FUNCTION create_delivery_order(p_customer jsonb, p_address jsonb, p_items jsonb, p_delivery_fee bigint, p_payment_mode text, p_cash_change_for bigint, p_notes text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_delivery_order(p_customer jsonb, p_address jsonb, p_items jsonb, p_delivery_fee bigint, p_payment_mode text, p_cash_change_for bigint, p_notes text) IS 'Atomic delivery-order intake. SECURITY DEFINER (owner postgres). Caller resolution through private.current_restaurant_id() / private.current_app_role() (42501 for non-admin/delivery_operator). Resolves or creates the customer by normalized phone (or by id when given) within the tenant; updates the existing customer''s name only when the request carries a different value. Resolves the address (an existing id must belong to that customer, or a new address is saved to the registry only when save=true). Validates p_items (1..100 lines, quantity 1..999), p_delivery_fee (>= 0), p_payment_mode (prepaid | cash_on_delivery), p_cash_change_for (only for COD, >= 0). Resolves each dish_id server-side from public.dishes and takes name/price from the menu (the client never sets the price). Inserts the order (order_type=delivery, table_id NULL, status=kitchen, waiter_id = caller profile, tax_percentage from business_config, tax/tip/total computed server-side), the order_items, and the order_deliveries row (snapshot of customer/address, fee, payment_mode, delivery_status=received). p_notes (trimmed, empty -> NULL, max 300) is stored on order_deliveries.notes. Returns jsonb with order_id, customer_id, address_id (NULL when save=false), and a delivery object with the order_deliveries row. P0002 for any cross-tenant customer/address/dish id; 22023 for bad input; 42501 for the wrong role.';


--
-- Name: customer_addresses_assert_consistency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_addresses_assert_consistency() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM private.assert_customer_address_consistent(OLD.id);
  ELSE
    PERFORM private.assert_customer_address_consistent(NEW.id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION customer_addresses_assert_consistency(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_addresses_assert_consistency() IS 'DEFERRABLE INITIALLY DEFERRED CONSTRAINT TRIGGER on public.customer_addresses: at COMMIT, re-checks every address touched by the transaction (same shape as public.payments_assert_consistency).';


--
-- Name: delete_order_with_items(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_order_with_items(p_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order_id     uuid;
  v_restaurant_id uuid;
BEGIN
  -- Resolve caller restaurant via JWT context
  SELECT restaurant_id INTO v_restaurant_id
    FROM public.profiles
   WHERE auth_user_id = auth.uid();

  IF v_restaurant_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: no profile found for user';
  END IF;

  -- Lock the order row and verify tenant ownership
  SELECT id INTO v_order_id
    FROM orders
   WHERE id = p_order_id AND restaurant_id = v_restaurant_id
     FOR UPDATE;

  IF v_order_id IS NULL THEN
    RAISE EXCEPTION 'Order not found or access denied: %', p_order_id;
  END IF;

  -- Delete junction links first (ingredient_transactions_orders ON DELETE CASCADE
  -- would handle this automatically, but explicit DELETE ensures FK RESTRICT on
  -- ingredient_transactions does not block)
  DELETE FROM ingredient_transactions_orders WHERE order_id = p_order_id;

  -- Delete order items (cascade FK handles this, but explicit for clarity)
  DELETE FROM order_items WHERE order_id = p_order_id;

  -- Delete the order (cascade would handle order_items, explicit for clarity)
  DELETE FROM orders WHERE id = p_order_id;
END;
$$;


--
-- Name: FUNCTION delete_order_with_items(p_order_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.delete_order_with_items(p_order_id uuid) IS 'Atomic order deletion: locks order, deletes ingredient_transactions_orders links, deletes order_items, deletes order. Tenant-scoped via caller JWT.';


--
-- Name: formulas_rpc_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.formulas_rpc_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  RAISE EXCEPTION '% is written only through save_formula', TG_TABLE_NAME USING ERRCODE = '42501';
END;
$$;


--
-- Name: FUNCTION formulas_rpc_only(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.formulas_rpc_only() IS 'SECURITY INVOKER BEFORE INSERT / UPDATE / DELETE on recipes and recipe_ingredients: direct client writes raise 42501; formulas change only through save_formula (and FK cascades, which run as the table owner).';


--
-- Name: guard_order_deliveries_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_order_deliveries_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'order_deliveries rows are immutable: writes are done by the task 3 SECURITY DEFINER RPCs'
    USING ERRCODE = 'insufficient_privilege';
END;
$$;


--
-- Name: FUNCTION guard_order_deliveries_immutable(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.guard_order_deliveries_immutable() IS 'BEFORE UPDATE OR DELETE guard on public.order_deliveries: a delivery row is written only by the task 3 SECURITY DEFINER RPCs. Raises insufficient_privilege (42501) for every caller except postgres / service_role / supabase_admin.';


--
-- Name: guard_payment_methods_code_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_payment_methods_code_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;

  IF NEW.code IS DISTINCT FROM OLD.code THEN
    RAISE EXCEPTION 'payment_methods.code is immutable'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION guard_payment_methods_code_immutable(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.guard_payment_methods_code_immutable() IS 'BEFORE UPDATE guard on public.payment_methods: code is immutable for every caller except postgres/service_role/supabase_admin, admin included. Raises insufficient_privilege (42501).';


--
-- Name: guard_payment_rows_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_payment_rows_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION '% rows are immutable: payments are written only by public.pay_order',
    TG_TABLE_NAME
    USING ERRCODE = 'insufficient_privilege';
END;
$$;


--
-- Name: FUNCTION guard_payment_rows_immutable(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.guard_payment_rows_immutable() IS 'BEFORE UPDATE OR DELETE guard on public.payments and public.payment_tenders: a payment is money history and is never rewritten or deleted by an authenticated caller. Raises insufficient_privilege (42501) for everyone except postgres/service_role/supabase_admin.';


--
-- Name: guard_payment_tender_snapshot_at_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_payment_tender_snapshot_at_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.payment_methods m
     WHERE m.id = NEW.payment_method_id AND m.code = NEW.method_code AND m.kind = NEW.method_kind) THEN
    RAISE EXCEPTION 'payment_tender snapshot does not match the catalog row at insert time (tender %)', NEW.id USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION guard_payment_tender_snapshot_at_insert(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.guard_payment_tender_snapshot_at_insert() IS 'BEFORE INSERT guard on public.payment_tenders: snapshot must match catalog at insert time, then is frozen.';


--
-- Name: guard_profiles_privileged_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_profiles_privileged_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;

  IF NEW.restaurant_id IS DISTINCT FROM OLD.restaurant_id THEN
    RAISE EXCEPTION 'profiles.restaurant_id is immutable'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id THEN
    RAISE EXCEPTION 'profiles.auth_user_id is immutable'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF NEW.role IS DISTINCT FROM OLD.role
     AND (SELECT private.current_app_role()) IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'only an admin of the same tenant may change profiles.role'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION guard_profiles_privileged_columns(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.guard_profiles_privileged_columns() IS 'BEFORE UPDATE guard on public.profiles: restaurant_id and auth_user_id are immutable for every caller except postgres/service_role/supabase_admin, and role only changes for an admin of the same tenant. Raises insufficient_privilege (42501).';


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_restaurant_id uuid;
  v_role text;
BEGIN
  v_role := COALESCE(NEW.raw_app_meta_data ->> 'role', 'waiter');

  v_restaurant_id := NULLIF(NEW.raw_app_meta_data ->> 'restaurant_id', '')::uuid;

  IF v_restaurant_id IS NULL THEN
    SELECT r.id INTO v_restaurant_id
    FROM public.restaurants r
    ORDER BY r.created_at, r.id
    LIMIT 1;
  END IF;

  INSERT INTO public.profiles (
    id, auth_user_id, email, full_name, role, restaurant_id, active, created_at, updated_at
  ) VALUES (
    gen_random_uuid(),
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data ->> 'full_name', split_part(NEW.email, '@', 1)),
    v_role,
    v_restaurant_id,
    true,
    now(),
    now()
  )
  ON CONFLICT (auth_user_id) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION handle_new_user(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.handle_new_user() IS 'AFTER INSERT on auth.users (Supabase Auth). Creates the profile with the role from raw_app_meta_data (server-controlled, defaults to waiter) and the tenant from raw_app_meta_data->>restaurant_id, else the oldest row of public.restaurants (ORDER BY created_at, id) - deterministic, but provisioning must set restaurant_id.';


--
-- Name: ingredients_inventory_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingredients_inventory_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_prefix    text;
  v_n         bigint;
  v_candidate text;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.kind = 'prep' AND NEW.kind <> 'prep'
     AND EXISTS (SELECT 1 FROM public.recipes r WHERE r.ingredient_id = NEW.id) THEN
    RAISE EXCEPTION 'ingredient % has a formula and must stay a preparation', NEW.id
      USING ERRCODE = 'P0001';
  END IF;

  NEW.sku := NULLIF(upper(btrim(NEW.sku)), '');

  IF NEW.sku IS NULL THEN
    v_prefix := CASE WHEN NEW.kind = 'prep' THEN 'PR-' ELSE 'MP-' END;
    LOOP
      v_n := private.next_inventory_counter(NEW.restaurant_id, 'sku_' || NEW.kind);
      v_candidate := v_prefix || lpad(v_n::text, greatest(4, length(v_n::text)), '0');
      EXIT WHEN NOT EXISTS (
        SELECT 1 FROM public.ingredients i
         WHERE i.restaurant_id = NEW.restaurant_id AND i.sku = v_candidate AND i.id <> NEW.id
      );
    END LOOP;
    NEW.sku := v_candidate;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION ingredients_inventory_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ingredients_inventory_guard() IS 'BEFORE INSERT / UPDATE OF sku, kind on public.ingredients: trims and uppercases the SKU, generates MP-0001 / PR-0001 per restaurant when it is blank, and refuses (P0001) turning a preparation with a formula into a raw item.';


--
-- Name: ingredients_stock_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingredients_stock_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' AND NEW.stock <> 0 THEN
    RAISE EXCEPTION 'ingredients.stock starts at 0; load stock through inventory_adjust (opening)'
      USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW.stock IS DISTINCT FROM OLD.stock OR NEW.cost IS DISTINCT FROM OLD.cost) THEN
    RAISE EXCEPTION 'ingredients.stock and cost are written only by the inventory RPCs'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION ingredients_stock_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ingredients_stock_guard() IS 'SECURITY INVOKER BEFORE INSERT / UPDATE OF stock, cost on public.ingredients: outside the inventory RPCs (current_user not postgres/service_role/supabase_admin) a new item must have stock 0 (cost may be set once as the initial reference cost) and stock / cost never change (42501).';


--
-- Name: inventory_adjust(uuid, uuid, text, numeric, numeric, text, text, uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_adjust(p_ingredient_id uuid, p_location_id uuid, p_movement_type text, p_quantity numeric, p_unit_cost numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_lot_id uuid DEFAULT NULL::uuid, p_lot_code text DEFAULT NULL::text, p_expires_on date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  c_fn constant text := 'inventory_adjust';
  v_caller record;
  v_item   public.ingredients%ROWTYPE;
  v_loc    uuid;
  v_signed numeric;
  v_cost   numeric;
  v_total  numeric := 0;
  v_lot    public.inventory_lots%ROWTYPE;
BEGIN
  SELECT * INTO v_caller FROM private.inventory_caller(c_fn, ARRAY['admin', 'kitchen']);

  IF p_movement_type IS NULL OR p_movement_type NOT IN ('opening', 'adjustment', 'waste') THEN
    RAISE EXCEPTION '%: p_movement_type must be opening, adjustment or waste', c_fn USING ERRCODE = '22023';
  END IF;
  IF v_caller.app_role <> 'admin' AND p_movement_type <> 'waste' THEN
    RAISE EXCEPTION '%: only admin may record %', c_fn, p_movement_type USING ERRCODE = '42501';
  END IF;
  IF p_quantity IS NULL OR p_quantity = 0 THEN
    RAISE EXCEPTION '%: p_quantity must be non-zero', c_fn USING ERRCODE = '22023';
  END IF;
  IF p_movement_type IN ('opening', 'waste') AND p_quantity < 0 THEN
    RAISE EXCEPTION '%: p_quantity must be positive for %', c_fn, p_movement_type USING ERRCODE = '22023';
  END IF;
  IF p_unit_cost IS NOT NULL AND p_unit_cost < 0 THEN
    RAISE EXCEPTION '%: p_unit_cost must be >= 0', c_fn USING ERRCODE = '22023';
  END IF;
  IF length(p_reason) > 200 THEN
    RAISE EXCEPTION '%: p_reason accepts at most 200 characters', c_fn USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_item FROM public.ingredients i
   WHERE i.id = p_ingredient_id AND i.restaurant_id = v_caller.restaurant_id
   FOR UPDATE;
  IF v_item.id IS NULL THEN
    RAISE EXCEPTION '%: ingredient % not found', c_fn, p_ingredient_id USING ERRCODE = 'P0002';
  END IF;

  v_loc := private.inventory_location(c_fn, v_caller.restaurant_id, p_location_id);
  v_signed := CASE WHEN p_movement_type = 'waste' THEN -p_quantity ELSE p_quantity END;

  IF v_signed > 0 THEN
    v_cost := COALESCE(p_unit_cost, v_item.cost, 0);
    IF p_unit_cost IS NOT NULL THEN
      PERFORM private.inventory_average_cost(v_item.id, v_signed, p_unit_cost);
    END IF;
    PERFORM private.inventory_put(v_caller.restaurant_id, v_item.id, v_loc, v_signed, v_cost,
                                  p_lot_code, p_expires_on, now(), p_movement_type, NULL, NULL,
                                  v_caller.profile_id, p_reason, p_notes);
    v_total := v_signed * v_cost;
  ELSIF p_lot_id IS NOT NULL THEN
    SELECT * INTO v_lot FROM public.inventory_lots l
     WHERE l.id = p_lot_id AND l.ingredient_id = v_item.id AND l.location_id = v_loc
     FOR UPDATE;
    IF v_lot.id IS NULL THEN
      RAISE EXCEPTION '%: lot % not found', c_fn, p_lot_id USING ERRCODE = 'P0002';
    END IF;
    IF v_lot.quantity < -v_signed THEN
      RAISE EXCEPTION '%: insufficient stock in lot (available %)', c_fn, v_lot.quantity USING ERRCODE = 'P0001';
    END IF;
    UPDATE public.inventory_lots SET quantity = quantity + v_signed WHERE id = v_lot.id;
    INSERT INTO public.inventory_movements
      (restaurant_id, ingredient_id, location_id, lot_id, movement_type, quantity, unit_cost,
       total_cost, reason, notes, created_by)
    VALUES (v_caller.restaurant_id, v_item.id, v_loc, v_lot.id, p_movement_type, v_signed, v_lot.unit_cost,
            v_signed * v_lot.unit_cost, p_reason, p_notes, v_caller.profile_id);
    v_total := v_signed * v_lot.unit_cost;
  ELSE
    v_total := -(private.inventory_take(v_caller.restaurant_id, v_item.id, v_loc, -v_signed, p_movement_type,
                                        NULL, NULL, v_caller.profile_id, false, p_reason, p_notes)->>'total_cost')::numeric;
  END IF;

  RETURN jsonb_build_object(
    'ingredient_id', v_item.id,
    'location_id', v_loc,
    'movement_type', p_movement_type,
    'quantity', v_signed::numeric(14,3),
    'total_cost', round(v_total, 4),
    'stock', private.inventory_sync_stock(v_item.id)
  );
END;
$$;


--
-- Name: FUNCTION inventory_adjust(p_ingredient_id uuid, p_location_id uuid, p_movement_type text, p_quantity numeric, p_unit_cost numeric, p_reason text, p_notes text, p_lot_id uuid, p_lot_code text, p_expires_on date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.inventory_adjust(p_ingredient_id uuid, p_location_id uuid, p_movement_type text, p_quantity numeric, p_unit_cost numeric, p_reason text, p_notes text, p_lot_id uuid, p_lot_code text, p_expires_on date) IS 'Manual stock change. p_movement_type: opening (> 0, admin), adjustment (signed, admin), waste (> 0, recorded negative; admin or kitchen). p_location_id NULL = default location. Positive: goes to the lot matching p_lot_code / p_expires_on (general when both NULL) at p_unit_cost (default ingredients.cost; an explicit cost updates the weighted-average cost). Negative: from p_lot_id when given, else FEFO; never below zero (P0001). Returns {ingredient_id, location_id, movement_type, quantity (signed), total_cost (signed), stock}. Errors: 22023 / P0002 / 42501 / P0001.';


--
-- Name: inventory_documents_before_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_documents_before_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_rpc     boolean := current_user IN ('postgres', 'service_role', 'supabase_admin');
  v_status  text;
  v_rid     uuid;
BEGIN
  IF TG_TABLE_NAME = 'purchase_orders' THEN
    IF TG_OP = 'INSERT' THEN
      IF NOT v_rpc AND NEW.status NOT IN ('draft', 'ordered') THEN
        RAISE EXCEPTION 'purchase orders start as draft or ordered' USING ERRCODE = 'P0001';
      END IF;
    ELSIF TG_OP = 'UPDATE' THEN
      IF NEW.number <> OLD.number THEN
        RAISE EXCEPTION 'purchase order numbers are immutable' USING ERRCODE = 'P0001';
      END IF;
      IF NOT v_rpc AND NEW.status IS DISTINCT FROM OLD.status
         AND NOT (OLD.status = 'draft' AND NEW.status IN ('ordered', 'cancelled'))
         AND NOT (OLD.status = 'ordered' AND NEW.status IN ('draft', 'cancelled')) THEN
        RAISE EXCEPTION 'purchase order cannot move from % to % (receipts go through receive_purchase_order)',
          OLD.status, NEW.status USING ERRCODE = 'P0001';
      END IF;
      IF NEW.status = 'ordered' AND OLD.status <> 'ordered' AND NEW.ordered_at IS NULL THEN
        NEW.ordered_at := now();
      END IF;
    ELSIF TG_OP = 'DELETE' THEN
      IF NOT v_rpc AND OLD.status <> 'draft' THEN
        RAISE EXCEPTION 'only draft purchase orders can be deleted' USING ERRCODE = 'P0001';
      END IF;
      RETURN OLD;
    END IF;

    IF TG_OP IN ('INSERT', 'UPDATE') THEN
      IF NOT EXISTS (SELECT 1 FROM public.suppliers s WHERE s.id = NEW.supplier_id AND s.restaurant_id = NEW.restaurant_id)
         OR NOT EXISTS (SELECT 1 FROM public.inventory_locations l WHERE l.id = NEW.location_id AND l.restaurant_id = NEW.restaurant_id) THEN
        RAISE EXCEPTION 'supplier and location must belong to the purchase order restaurant' USING ERRCODE = 'P0002';
      END IF;
    END IF;
    RETURN NEW;

  ELSIF TG_TABLE_NAME = 'purchase_order_lines' THEN
    SELECT po.status, po.restaurant_id INTO v_status, v_rid
      FROM public.purchase_orders po
     WHERE po.id = CASE WHEN TG_OP = 'DELETE' THEN OLD.purchase_order_id ELSE NEW.purchase_order_id END;

    IF NOT v_rpc AND v_status NOT IN ('draft', 'ordered') THEN
      RAISE EXCEPTION 'purchase order lines can only change while the order is draft or ordered'
        USING ERRCODE = 'P0001';
    END IF;
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    IF NOT v_rpc AND NEW.received_quantity IS DISTINCT FROM
       (CASE WHEN TG_OP = 'UPDATE' THEN OLD.received_quantity ELSE 0 END) THEN
      RAISE EXCEPTION 'received_quantity is written by receive_purchase_order only' USING ERRCODE = '42501';
    END IF;
    -- The line always follows its order's tenant; RLS WITH CHECK then refuses
    -- a line that points at another tenant's order.
    NEW.restaurant_id := COALESCE(v_rid, NEW.restaurant_id);
    IF NOT EXISTS (SELECT 1 FROM public.ingredients i WHERE i.id = NEW.ingredient_id AND i.restaurant_id = NEW.restaurant_id) THEN
      RAISE EXCEPTION 'ingredient % not found', NEW.ingredient_id USING ERRCODE = 'P0002';
    END IF;
    RETURN NEW;

  ELSIF TG_TABLE_NAME = 'inventory_counts' THEN
    IF TG_OP = 'UPDATE' AND NOT v_rpc THEN
      IF OLD.status <> 'open' THEN
        RAISE EXCEPTION 'count % is %', OLD.number, OLD.status USING ERRCODE = 'P0001';
      END IF;
      IF NEW.status NOT IN ('open', 'cancelled') THEN
        RAISE EXCEPTION 'counts are applied through apply_inventory_count' USING ERRCODE = 'P0001';
      END IF;
      IF NEW.number <> OLD.number
         OR NEW.location_id <> OLD.location_id OR NEW.applied_at IS DISTINCT FROM OLD.applied_at THEN
        RAISE EXCEPTION 'counts are applied through apply_inventory_count' USING ERRCODE = '42501';
      END IF;
    END IF;
    RETURN NEW;

  ELSIF TG_TABLE_NAME = 'inventory_count_lines' THEN
    IF NOT v_rpc THEN
      SELECT c.status INTO v_status FROM public.inventory_counts c WHERE c.id = OLD.count_id;
      IF v_status <> 'open' THEN
        RAISE EXCEPTION 'count lines can only change while the count is open' USING ERRCODE = 'P0001';
      END IF;
      IF NEW.count_id <> OLD.count_id OR NEW.ingredient_id <> OLD.ingredient_id
         OR NEW.expected_quantity <> OLD.expected_quantity OR NEW.restaurant_id <> OLD.restaurant_id THEN
        RAISE EXCEPTION 'only counted_quantity and notes are editable' USING ERRCODE = '42501';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION inventory_documents_before_write(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.inventory_documents_before_write() IS 'SECURITY INVOKER BEFORE trigger for purchase_orders, purchase_order_lines, inventory_counts and inventory_count_lines. Direct (non-RPC, i.e. current_user not postgres/service_role/supabase_admin) writes: purchase orders only draft <-> ordered -> cancelled, received/partially_received only via receive_purchase_order (P0001); received_quantity only via the RPC (42501); counts only open -> cancelled, applied only via apply_inventory_count (P0001); count lines only counted_quantity / notes (42501). Keeps lines in their parent tenant.';


--
-- Name: inventory_documents_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_documents_number() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.number IS NULL THEN
    NEW.number := private.next_inventory_counter(NEW.restaurant_id,
      CASE TG_TABLE_NAME WHEN 'purchase_orders' THEN 'purchase_order' ELSE 'inventory_count' END);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION inventory_documents_number(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.inventory_documents_number() IS 'BEFORE INSERT on purchase_orders / inventory_counts: assigns the next per-restaurant number when it is NULL.';


--
-- Name: inventory_locations_default_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_locations_default_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF pg_trigger_depth() > 1 THEN
    RETURN NEW;
  END IF;
  IF OLD.is_default AND NOT NEW.is_default THEN
    RAISE EXCEPTION 'location % is the default; mark another location as default instead', OLD.code
      USING ERRCODE = 'P0001';
  END IF;
  IF NEW.is_default AND NOT OLD.is_default THEN
    UPDATE public.inventory_locations
       SET is_default = false
     WHERE restaurant_id = NEW.restaurant_id AND is_default AND id <> NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION inventory_locations_default_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.inventory_locations_default_guard() IS 'BEFORE UPDATE OF is_default on public.inventory_locations: setting is_default moves the default from the previous one; clearing the only default raises P0001.';


--
-- Name: inventory_overview(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_overview(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  c_fn constant text := 'inventory_overview';
  v_caller record;
  v_tz     text;
  v_today  date;
  v_from   date;
  v_start  timestamptz;
  v_kpis   jsonb;
  v_series jsonb;
  v_cats   jsonb;
  v_top    jsonb;
BEGIN
  SELECT * INTO v_caller FROM private.inventory_caller(c_fn, ARRAY['admin']);

  IF p_days IS NULL OR p_days NOT BETWEEN 1 AND 365 THEN
    RAISE EXCEPTION '%: p_days must be between 1 and 365', c_fn USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(r.timezone, 'America/Bogota') INTO v_tz FROM public.restaurants r WHERE r.id = v_caller.restaurant_id;
  v_today := (now() AT TIME ZONE v_tz)::date;
  v_from := v_today - (p_days - 1);
  v_start := v_from::timestamp AT TIME ZONE v_tz;

  SELECT jsonb_build_object(
    'total_value', COALESCE((SELECT round(sum(l.quantity * l.unit_cost), 2) FROM public.inventory_lots l
                              WHERE l.restaurant_id = v_caller.restaurant_id AND l.quantity > 0), 0),
    'items_count', (SELECT count(*) FROM public.ingredients i WHERE i.restaurant_id = v_caller.restaurant_id),
    'active_items', (SELECT count(*) FROM public.ingredients i WHERE i.restaurant_id = v_caller.restaurant_id AND i.is_active),
    'low_stock_count', (SELECT count(*) FROM public.ingredients i
                         WHERE i.restaurant_id = v_caller.restaurant_id AND i.is_active
                           AND i.min_stock > 0 AND i.stock > 0 AND i.stock <= i.min_stock),
    'out_of_stock_count', (SELECT count(*) FROM public.ingredients i
                            WHERE i.restaurant_id = v_caller.restaurant_id AND i.is_active AND i.stock <= 0),
    'expiring_soon_count', (SELECT count(*) FROM public.inventory_lots l
                             WHERE l.restaurant_id = v_caller.restaurant_id AND l.quantity > 0
                               AND l.expires_on BETWEEN v_today AND v_today + 7),
    'expired_count', (SELECT count(*) FROM public.inventory_lots l
                       WHERE l.restaurant_id = v_caller.restaurant_id AND l.quantity > 0 AND l.expires_on < v_today),
    'waste_value', COALESCE((SELECT round(-sum(m.total_cost), 2) FROM public.inventory_movements m
                              WHERE m.restaurant_id = v_caller.restaurant_id AND m.created_at >= v_start
                                AND m.movement_type = 'waste'), 0),
    'purchases_value', COALESCE((SELECT round(sum(m.total_cost), 2) FROM public.inventory_movements m
                                  WHERE m.restaurant_id = v_caller.restaurant_id AND m.created_at >= v_start
                                    AND m.movement_type = 'purchase'), 0),
    'consumption_value', COALESCE((SELECT round(-sum(m.total_cost), 2) FROM public.inventory_movements m
                                    WHERE m.restaurant_id = v_caller.restaurant_id AND m.created_at >= v_start
                                      AND m.movement_type IN ('sale', 'production_consume')), 0),
    'open_purchase_orders', (SELECT count(*) FROM public.purchase_orders po
                              WHERE po.restaurant_id = v_caller.restaurant_id
                                AND po.status IN ('ordered', 'partially_received'))
  ) INTO v_kpis;

  SELECT jsonb_agg(jsonb_build_object(
           'date', d.day,
           'in_value', COALESCE(s.in_value, 0),
           'out_value', COALESCE(s.out_value, 0),
           'waste_value', COALESCE(s.waste_value, 0)) ORDER BY d.day)
    INTO v_series
    FROM generate_series(v_from, v_today, interval '1 day') AS g(ts)
    CROSS JOIN LATERAL (SELECT g.ts::date AS day) d
    LEFT JOIN (
      SELECT (m.created_at AT TIME ZONE v_tz)::date AS day,
             round(sum(m.total_cost) FILTER (WHERE m.quantity > 0
                   AND m.movement_type NOT IN ('transfer_in')), 2) AS in_value,
             round(-sum(m.total_cost) FILTER (WHERE m.movement_type IN ('sale', 'production_consume')), 2) AS out_value,
             round(-sum(m.total_cost) FILTER (WHERE m.movement_type = 'waste'), 2) AS waste_value
        FROM public.inventory_movements m
       WHERE m.restaurant_id = v_caller.restaurant_id AND m.created_at >= v_start
       GROUP BY 1
    ) s ON s.day = d.day;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'category_id', c.category_id, 'category_name', c.category_name, 'value', c.value)
           ORDER BY c.value DESC), '[]'::jsonb)
    INTO v_cats
    FROM (
      SELECT i.category_id, COALESCE(ic.name, 'Sin categoría') AS category_name,
             round(sum(l.quantity * l.unit_cost), 2) AS value
        FROM public.inventory_lots l
        JOIN public.ingredients i ON i.id = l.ingredient_id
        LEFT JOIN public.ingredient_categories ic ON ic.id = i.category_id
       WHERE l.restaurant_id = v_caller.restaurant_id AND l.quantity > 0
       GROUP BY i.category_id, ic.name
    ) c;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'ingredient_id', t.ingredient_id, 'name', t.name, 'unit', t.unit,
           'quantity', t.quantity, 'value', t.value) ORDER BY t.value DESC, t.name), '[]'::jsonb)
    INTO v_top
    FROM (
      SELECT i.id AS ingredient_id, i.name, i.unit,
             -sum(m.quantity) AS quantity, round(-sum(m.total_cost), 2) AS value
        FROM public.inventory_movements m
        JOIN public.ingredients i ON i.id = m.ingredient_id
       WHERE m.restaurant_id = v_caller.restaurant_id AND m.created_at >= v_start
         AND m.movement_type IN ('sale', 'production_consume')
       GROUP BY i.id, i.name, i.unit
       ORDER BY 5 DESC, i.name
       LIMIT 10
    ) t;

  RETURN jsonb_build_object(
    'days', p_days,
    'generated_at', now(),
    'kpis', v_kpis,
    'series', v_series,
    'value_by_category', v_cats,
    'top_consumed', v_top
  );
END;
$$;


--
-- Name: FUNCTION inventory_overview(p_days integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.inventory_overview(p_days integer) IS 'Inventory dashboard data for the last p_days (1..365) in the restaurant timezone, admin only. Returns {days, generated_at, kpis:{total_value, items_count, active_items, low_stock_count, out_of_stock_count, expiring_soon_count (positive lots expiring within 7 days), expired_count, waste_value, purchases_value, consumption_value (sale + production_consume), open_purchase_orders}, series:[{date, in_value, out_value, waste_value}] one point per day, value_by_category:[{category_id, category_name, value}], top_consumed:[{ingredient_id, name, unit, quantity, value}] (top 10 by value)}. Values are cost amounts (quantity x unit_cost).';


--
-- Name: inventory_transfer(uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer(p_ingredient_id uuid, p_from_location_id uuid, p_to_location_id uuid, p_quantity numeric, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  c_fn constant text := 'inventory_transfer';
  v_caller   record;
  v_item     public.ingredients%ROWTYPE;
  v_from     uuid;
  v_to       uuid;
  v_id       uuid := gen_random_uuid();
  v_taken    jsonb;
  v_portion  jsonb;
BEGIN
  SELECT * INTO v_caller FROM private.inventory_caller(c_fn, ARRAY['admin']);

  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RAISE EXCEPTION '%: p_quantity must be positive', c_fn USING ERRCODE = '22023';
  END IF;
  IF p_from_location_id IS NULL OR p_to_location_id IS NULL OR p_from_location_id = p_to_location_id THEN
    RAISE EXCEPTION '%: source and destination must be two different locations', c_fn USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_item FROM public.ingredients i
   WHERE i.id = p_ingredient_id AND i.restaurant_id = v_caller.restaurant_id
   FOR UPDATE;
  IF v_item.id IS NULL THEN
    RAISE EXCEPTION '%: ingredient % not found', c_fn, p_ingredient_id USING ERRCODE = 'P0002';
  END IF;
  v_from := private.inventory_location(c_fn, v_caller.restaurant_id, p_from_location_id);
  v_to := private.inventory_location(c_fn, v_caller.restaurant_id, p_to_location_id);

  v_taken := private.inventory_take(v_caller.restaurant_id, v_item.id, v_from, p_quantity, 'transfer_out',
                                    'transfer', v_id, v_caller.profile_id, false, NULL, p_notes);

  FOR v_portion IN SELECT * FROM jsonb_array_elements(v_taken->'portions') LOOP
    PERFORM private.inventory_put(v_caller.restaurant_id, v_item.id, v_to,
                                  (v_portion->>'quantity')::numeric, (v_portion->>'unit_cost')::numeric,
                                  v_portion->>'lot_code', (v_portion->>'expires_on')::date,
                                  (v_portion->>'received_at')::timestamptz, 'transfer_in',
                                  'transfer', v_id, v_caller.profile_id, NULL, p_notes);
  END LOOP;

  PERFORM private.inventory_sync_stock(v_item.id);

  RETURN jsonb_build_object(
    'transfer_id', v_id,
    'ingredient_id', v_item.id,
    'from_location_id', v_from,
    'to_location_id', v_to,
    'quantity', p_quantity::numeric(14,3),
    'total_cost', round((v_taken->>'total_cost')::numeric, 4)
  );
END;
$$;


--
-- Name: FUNCTION inventory_transfer(p_ingredient_id uuid, p_from_location_id uuid, p_to_location_id uuid, p_quantity numeric, p_notes text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.inventory_transfer(p_ingredient_id uuid, p_from_location_id uuid, p_to_location_id uuid, p_quantity numeric, p_notes text) IS 'Moves p_quantity (> 0) of an item between two active locations of the tenant (admin). Takes FEFO from the source and recreates each portion at the destination with the same lot_code, expires_on, received_at and unit_cost (transfer_out / transfer_in movements sharing reference transfer:<transfer_id>). Never below zero (P0001). Returns {transfer_id, ingredient_id, from_location_id, to_location_id, quantity, total_cost}.';


--
-- Name: open_inventory_count(uuid, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_inventory_count(p_location_id uuid DEFAULT NULL::uuid, p_ingredient_ids uuid[] DEFAULT NULL::uuid[], p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  c_fn constant text := 'open_inventory_count';
  v_caller record;
  v_loc    uuid;
  v_count  public.inventory_counts%ROWTYPE;
  v_lines  integer;
BEGIN
  SELECT * INTO v_caller FROM private.inventory_caller(c_fn, ARRAY['admin']);
  v_loc := private.inventory_location(c_fn, v_caller.restaurant_id, p_location_id);

  IF p_ingredient_ids IS NOT NULL THEN
    IF cardinality(p_ingredient_ids) = 0 THEN
      RAISE EXCEPTION '%: p_ingredient_ids must not be empty (use NULL for every active item)', c_fn
        USING ERRCODE = '22023';
    END IF;
    IF EXISTS (SELECT 1 FROM unnest(p_ingredient_ids) x(id)
                WHERE NOT EXISTS (SELECT 1 FROM public.ingredients i
                                   WHERE i.id = x.id AND i.restaurant_id = v_caller.restaurant_id)) THEN
      RAISE EXCEPTION '%: an ingredient was not found', c_fn USING ERRCODE = 'P0002';
    END IF;
  END IF;

  INSERT INTO public.inventory_counts (restaurant_id, location_id, notes, created_by)
  VALUES (v_caller.restaurant_id, v_loc, p_notes, v_caller.profile_id)
  RETURNING * INTO v_count;

  INSERT INTO public.inventory_count_lines (restaurant_id, count_id, ingredient_id, expected_quantity)
  SELECT v_caller.restaurant_id, v_count.id, i.id,
         COALESCE((SELECT sum(l.quantity) FROM public.inventory_lots l
                    WHERE l.ingredient_id = i.id AND l.location_id = v_loc), 0)
    FROM public.ingredients i
   WHERE i.restaurant_id = v_caller.restaurant_id
     AND (CASE WHEN p_ingredient_ids IS NULL THEN i.is_active ELSE i.id = ANY (p_ingredient_ids) END);
  GET DIAGNOSTICS v_lines = ROW_COUNT;

  RETURN jsonb_build_object(
    'count_id', v_count.id,
    'number', v_count.number,
    'location_id', v_loc,
    'status', v_count.status,
    'lines_count', v_lines
  );
END;
$$;


--
-- Name: FUNCTION open_inventory_count(p_location_id uuid, p_ingredient_ids uuid[], p_notes text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.open_inventory_count(p_location_id uuid, p_ingredient_ids uuid[], p_notes text) IS 'Opens a physical count at a location (NULL = default), admin only, with one line per item (p_ingredient_ids, or every active item when NULL) carrying expected_quantity = current location balance. Admin then fills inventory_count_lines.counted_quantity. Returns {count_id, number, location_id, status, lines_count}.';


--
-- Name: order_deliveries_assert_consistency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.order_deliveries_assert_consistency() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM private.assert_order_delivery_consistent(OLD.order_id);
  ELSE
    PERFORM private.assert_order_delivery_consistent(NEW.order_id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION order_deliveries_assert_consistency(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.order_deliveries_assert_consistency() IS 'DEFERRABLE INITIALLY DEFERRED CONSTRAINT TRIGGER on public.order_deliveries: at COMMIT, re-checks every delivery row touched by the transaction (same shape as public.payments_assert_consistency).';


--
-- Name: pay_order(uuid, uuid, bigint, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_order(p_order_id uuid, p_cash_register_id uuid, p_tip_amount bigint, p_tenders jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_caller_tenant   uuid;
  v_caller_role     text;
  v_caller_profile  uuid;

  v_order           public.orders%ROWTYPE;
  v_register        public.cash_registers%ROWTYPE;
  v_delivery_fee    bigint := 0;

  v_subtotal        bigint := 0;
  v_tax             bigint := 0;
  v_amount_due      bigint := 0;

  v_tender_count    integer;
  v_tenders_sum     bigint := 0;
  v_change_given    bigint := 0;
  v_cash_received_sum bigint := 0;

  v_existing        public.payments%ROWTYPE;
  v_payment_id      uuid;

  v_drawer_cash_before bigint := 0;
  v_drawer_warning  boolean := false;

  v_tender          jsonb;
  v_method_id       uuid;
  v_method_code     text;
  v_method_kind     text;
  v_method_active   boolean;
  v_method_tenant   uuid;
  v_amount          bigint;
  v_cash_received   bigint;

  v_line_no         smallint := 0;
  v_tender_json     jsonb;
  v_tender_lines    jsonb := '[]'::jsonb;

  v_pending_line_no        smallint[] := '{}'::smallint[];
  v_pending_payment_method uuid[]    := '{}'::uuid[];
  v_pending_amount         bigint[]  := '{}'::bigint[];
  v_pending_cash_received  bigint[]  := '{}'::bigint[];

  v_i              integer;
BEGIN
  -- 1. Caller resolution.
  v_caller_tenant := private.current_restaurant_id();
  v_caller_role   := private.current_app_role();

  IF v_caller_tenant IS NULL OR v_caller_role IS NULL THEN
    RAISE EXCEPTION 'pay_order: the caller has no profile'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- CHANGE 1: delivery_operator is admitted so the operator can record a
  -- prepaid payment or a cash-on-delivery collection without handing the
  -- drawer to a cashier.
  IF v_caller_role NOT IN ('cashier', 'admin', 'delivery_operator') THEN
    RAISE EXCEPTION 'pay_order: only cashier, admin or delivery_operator may settle an order'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT p.id INTO v_caller_profile
    FROM public.profiles p
   WHERE p.auth_user_id = auth.uid()
   LIMIT 1;

  IF v_caller_profile IS NULL THEN
    RAISE EXCEPTION 'pay_order: the caller has no profile'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 2. Input validation.
  IF p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'pay_order: p_idempotency_key must not be null'
      USING ERRCODE = '22023';
  END IF;

  IF p_tip_amount IS NULL OR p_tip_amount < 0 THEN
    RAISE EXCEPTION 'pay_order: p_tip_amount must be a non-negative integer'
      USING ERRCODE = '22023';
  END IF;

  IF p_tenders IS NULL OR jsonb_typeof(p_tenders) <> 'array' OR jsonb_array_length(p_tenders) = 0 THEN
    RAISE EXCEPTION 'pay_order: p_tenders must be a non-empty JSON array'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_array_length(p_tenders) > 20 THEN
    RAISE EXCEPTION 'pay_order: p_tenders accepts at most 20 lines'
      USING ERRCODE = '22023';
  END IF;

  v_tender_count := jsonb_array_length(p_tenders);

  FOR v_line_no IN 1..v_tender_count LOOP
    v_tender := p_tenders -> (v_line_no - 1);

    IF v_tender IS NULL OR jsonb_typeof(v_tender) <> 'object' THEN
      RAISE EXCEPTION 'pay_order: tender[%] must be a JSON object', v_line_no
        USING ERRCODE = '22023';
    END IF;

    IF NOT (v_tender ? 'payment_method_id') THEN
      RAISE EXCEPTION 'pay_order: tender[%] is missing payment_method_id', v_line_no
        USING ERRCODE = '22023';
    END IF;

    BEGIN
      v_method_id := (v_tender ->> 'payment_method_id')::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'pay_order: tender[%].payment_method_id is not a uuid', v_line_no
        USING ERRCODE = '22023';
    END;

    IF NOT (v_tender ? 'amount') THEN
      RAISE EXCEPTION 'pay_order: tender[%] is missing amount', v_line_no
        USING ERRCODE = '22023';
    END IF;

    BEGIN
      v_amount := (v_tender ->> 'amount')::bigint;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'pay_order: tender[%].amount is not an integer', v_line_no
        USING ERRCODE = '22023';
    END;

    IF v_amount IS NULL OR v_amount <= 0 THEN
      RAISE EXCEPTION 'pay_order: tender[%].amount must be a positive integer', v_line_no
        USING ERRCODE = '22023';
    END IF;

    IF v_tender ? 'cash_received' AND v_tender -> 'cash_received' IS NOT NULL AND v_tender -> 'cash_received' <> 'null'::jsonb THEN
      BEGIN
        v_cash_received := (v_tender ->> 'cash_received')::bigint;
      EXCEPTION WHEN others THEN
        RAISE EXCEPTION 'pay_order: tender[%].cash_received is not an integer', v_line_no
          USING ERRCODE = '22023';
      END;
    ELSE
      v_cash_received := NULL;
    END IF;

    v_pending_line_no        := v_pending_line_no || v_line_no;
    v_pending_payment_method := v_pending_payment_method || v_method_id;
    v_pending_amount         := v_pending_amount || v_amount;
    v_pending_cash_received  := v_pending_cash_received || v_cash_received;
  END LOOP;

  -- 3. Order.
  SELECT o.* INTO v_order
    FROM public.orders o
   WHERE o.id = p_order_id
     FOR UPDATE;

  IF NOT FOUND OR v_order.restaurant_id <> v_caller_tenant THEN
    RAISE EXCEPTION 'pay_order: order % not found', p_order_id
      USING ERRCODE = 'P0002';
  END IF;

  -- Existing payment for this order? UNIQUE (order_id) makes this a 0/1
  -- decision.
  SELECT p.* INTO v_existing
    FROM public.payments p
   WHERE p.order_id = p_order_id;

  IF FOUND THEN
    IF v_existing.idempotency_key = p_idempotency_key THEN
      SELECT coalesce(jsonb_agg(jsonb_build_object(
                 'line_no', t.line_no,
                 'method_code', t.method_code,
                 'amount', t.amount,
                 'cash_received', t.cash_received)
                 ORDER BY t.line_no), '[]'::jsonb)
        INTO v_tender_lines
        FROM public.payment_tenders t
       WHERE t.payment_id = v_existing.id;

      RETURN jsonb_build_object(
        'payment_id',         v_existing.id,
        'status',             'already_paid',
        'amount_due',         v_existing.amount_due,
        'tip_amount',         v_existing.tip_amount,
        'total_charged',      v_existing.total_charged,
        'change_given',       v_existing.change_given,
        'drawer_warning',     false,
        'drawer_cash_before', 0,
        'tenders',            v_tender_lines
      );
    ELSE
      RAISE EXCEPTION 'pay_order: order % is already paid', p_order_id
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF v_order.status NOT IN ('active', 'kitchen', 'delivered') THEN
    RAISE EXCEPTION 'pay_order: order % cannot be paid (status=%)',
      p_order_id, v_order.status
      USING ERRCODE = 'P0001';
  END IF;

  -- 4. Cash register.
  SELECT r.* INTO v_register
    FROM public.cash_registers r
   WHERE r.id = p_cash_register_id
     FOR SHARE;

  IF NOT FOUND OR v_register.restaurant_id <> v_caller_tenant THEN
    RAISE EXCEPTION 'pay_order: cash register % not found', p_cash_register_id
      USING ERRCODE = 'P0001';
  END IF;

  IF v_register.status <> 'open' THEN
    RAISE EXCEPTION 'pay_order: cash register % is not open (status=%)',
      p_cash_register_id, v_register.status
      USING ERRCODE = 'P0001';
  END IF;

  -- 5. Server-side amount.
  SELECT coalesce(sum(round(oi.price * oi.quantity)), 0)::bigint
    INTO v_subtotal
    FROM public.order_items oi
   WHERE oi.order_id = p_order_id
     AND oi.restaurant_id = v_caller_tenant;

  IF v_subtotal <= 0 THEN
    RAISE EXCEPTION 'pay_order: order % has no items', p_order_id
      USING ERRCODE = 'P0001';
  END IF;

  v_tax := round(v_subtotal * coalesce(v_order.tax_percentage, 0)::numeric / 100)::bigint;

  -- CHANGE 2: add the delivery fee when the order is a delivery. The
  -- order_deliveries row is guaranteed to exist by the consistency trigger
  -- (1:1 with the order, same restaurant). No tax on the fee, no tip on the
  -- fee: the tax is computed on the food subtotal only, and the tip is the
  -- caller's p_tip_amount as today.
  v_delivery_fee := 0;
  IF v_order.order_type = 'delivery' THEN
    SELECT coalesce(od.delivery_fee, 0)
      INTO v_delivery_fee
      FROM public.order_deliveries od
     WHERE od.order_id = p_order_id;

    IF v_delivery_fee IS NULL THEN
      -- A delivery order with no order_deliveries row is a schema invariant
      -- break. The 23514 from the consistency trigger would already have
      -- fired; this is a defense in depth.
      v_delivery_fee := 0;
    END IF;
  END IF;

  v_amount_due := v_subtotal + v_tax + v_delivery_fee;

  -- 6. Tenders.
  FOR v_i IN 1..array_length(v_pending_line_no, 1) LOOP
    v_line_no        := v_pending_line_no[v_i];
    v_method_id      := v_pending_payment_method[v_i];
    v_amount         := v_pending_amount[v_i];
    v_cash_received  := v_pending_cash_received[v_i];

    SELECT m.code, m.kind, m.is_active, m.restaurant_id
      INTO v_method_code, v_method_kind, v_method_active, v_method_tenant
      FROM public.payment_methods m
     WHERE m.id = v_method_id;

    IF NOT FOUND OR v_method_tenant <> v_caller_tenant THEN
      RAISE EXCEPTION 'pay_order: tender[%].payment_method_id does not resolve to a method of the caller tenant', v_line_no
        USING ERRCODE = 'P0001';
    END IF;

    IF NOT v_method_active THEN
      RAISE EXCEPTION 'pay_order: tender[%].payment_method_id resolves to an inactive method (% of tenant %)',
        v_line_no, v_method_code, v_method_tenant
        USING ERRCODE = 'P0001';
    END IF;

    v_tenders_sum := v_tenders_sum + v_amount;

    IF v_method_kind = 'cash' THEN
      IF v_cash_received IS NULL THEN
        RAISE EXCEPTION 'pay_order: tender[%] is a cash method but cash_received is NULL', v_line_no
          USING ERRCODE = 'P0001';
      END IF;
      IF v_cash_received < v_amount THEN
        RAISE EXCEPTION 'pay_order: tender[%].cash_received (%) is below amount (%)',
          v_line_no, v_cash_received, v_amount
          USING ERRCODE = 'P0001';
      END IF;
      v_change_given := v_change_given + (v_cash_received - v_amount);
      v_cash_received_sum := v_cash_received_sum + v_cash_received;
    ELSE
      IF v_cash_received IS NOT NULL THEN
        RAISE EXCEPTION 'pay_order: tender[%] is an electronic method but cash_received is not NULL', v_line_no
          USING ERRCODE = 'P0001';
      END IF;
    END IF;
  END LOOP;

  IF v_tenders_sum <> (v_amount_due + p_tip_amount) THEN
    RAISE EXCEPTION 'pay_order: tenders sum to % but amount_due + tip = %',
      v_tenders_sum, (v_amount_due + p_tip_amount)
      USING ERRCODE = 'P0001';
  END IF;

  -- 7. Drawer warning (warn only).
  v_drawer_cash_before := v_register.initial_cash;

  SELECT coalesce(v_drawer_cash_before + sum(t.amount), v_drawer_cash_before)::bigint
    INTO v_drawer_cash_before
    FROM public.payment_tenders t
    JOIN public.payments p ON p.id = t.payment_id
   WHERE p.cash_register_id = p_cash_register_id
     AND t.method_kind = 'cash';

  SELECT coalesce(v_drawer_cash_before
                  + coalesce(sum(CASE WHEN ct.type = 'deposit' THEN ct.amount ELSE 0 END), 0)
                  - coalesce(sum(CASE WHEN ct.type = 'withdrawal' THEN ct.amount ELSE 0 END), 0),
                  v_drawer_cash_before)::bigint
    INTO v_drawer_cash_before
    FROM public.cash_transactions ct
   WHERE ct.cash_register_id = p_cash_register_id;

  v_drawer_warning := v_change_given > v_drawer_cash_before;

  -- 8. Writes.
  INSERT INTO public.payments (
    restaurant_id, order_id, cash_register_id, cashier_profile_id,
    amount_due, tip_amount, total_charged, change_given, idempotency_key
  ) VALUES (
    v_caller_tenant, p_order_id, p_cash_register_id, v_caller_profile,
    v_amount_due, p_tip_amount, v_amount_due + p_tip_amount, v_change_given, p_idempotency_key
  )
  RETURNING id INTO v_payment_id;

  FOR v_i IN 1..array_length(v_pending_line_no, 1) LOOP
    v_line_no        := v_pending_line_no[v_i];
    v_method_id      := v_pending_payment_method[v_i];
    v_amount         := v_pending_amount[v_i];
    v_cash_received  := v_pending_cash_received[v_i];

    SELECT m.code, m.kind
      INTO v_method_code, v_method_kind
      FROM public.payment_methods m
     WHERE m.id = v_method_id;

    INSERT INTO public.payment_tenders (
      restaurant_id, payment_id, line_no, payment_method_id,
      method_code, method_kind, amount, cash_received
    ) VALUES (
      v_caller_tenant, v_payment_id, v_line_no, v_method_id,
      v_method_code, v_method_kind, v_amount, v_cash_received
    );
  END LOOP;

  -- 9. Order update. tip_percentage is the tip / subtotal ratio (the food
  -- subtotal, NOT amount_due), the same as the original pay_order.
  UPDATE public.orders o
     SET subtotal = v_subtotal,
         tax = v_tax,
         tip = p_tip_amount,
         tip_percentage = CASE WHEN v_subtotal > 0
                               THEN round((p_tip_amount * 100.0 / v_subtotal)::numeric, 2)
                               ELSE 0 END,
         total = v_amount_due + p_tip_amount,
         status = 'paid',
         updated_at = now()
   WHERE o.id = p_order_id;

  -- 10. Table release (delivery orders have table_id NULL; the IF guard
  -- already short-circuits).
  IF v_order.table_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.orders o
       WHERE o.table_id = v_order.table_id
         AND o.id <> p_order_id
         AND o.status IN ('active', 'kitchen', 'delivered')
    ) THEN
      UPDATE public.tables t
         SET status = 'available',
             updated_at = now()
       WHERE t.id = v_order.table_id;
    END IF;
  END IF;

  -- 11. Response.
  RETURN jsonb_build_object(
    'payment_id',         v_payment_id,
    'status',             'paid',
    'amount_due',         v_amount_due,
    'tip_amount',         p_tip_amount,
    'total_charged',      v_amount_due + p_tip_amount,
    'change_given',       v_change_given,
    'drawer_warning',     v_drawer_warning,
    'drawer_cash_before', v_drawer_cash_before,
    'tenders',            (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'line_no',        t.line_no,
        'method_code',    t.method_code,
        'amount',         t.amount,
        'cash_received',  t.cash_received
      ) ORDER BY t.line_no), '[]'::jsonb)
        FROM public.payment_tenders t
       WHERE t.payment_id = v_payment_id
    )
  );
END;
$$;


--
-- Name: FUNCTION pay_order(p_order_id uuid, p_cash_register_id uuid, p_tip_amount bigint, p_tenders jsonb, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pay_order(p_order_id uuid, p_cash_register_id uuid, p_tip_amount bigint, p_tenders jsonb, p_idempotency_key uuid) IS 'Atomic checkout. SECURITY DEFINER (owner postgres). Locks the order, validates the caller is a cashier/admin/delivery_operator of the tenant, the register is open and of the tenant, the order is active|kitchen|delivered with at least one line, and the tenders add up to amount_due + tip. For a delivery order, amount_due = subtotal + tax + delivery_fee (no tax / no tip on the fee). Snapshots the catalog (method_code / method_kind) so a later rename or retype does not rewrite history. Idempotent on (restaurant_id, idempotency_key): a replay returns status=already_paid with the existing payment summary and writes nothing; a different key on a paid order raises P0001. Returns jsonb with payment_id, status, amount_due, tip_amount, total_charged, change_given, drawer_warning, drawer_cash_before, tenders.';


--
-- Name: payment_methods_set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_methods_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION payment_methods_set_updated_at(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.payment_methods_set_updated_at() IS 'BEFORE UPDATE on public.payment_methods: stamps updated_at.';


--
-- Name: payments_assert_consistency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payments_assert_consistency() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'payments' THEN
    IF TG_OP = 'DELETE' THEN
      PERFORM private.assert_payment_consistent(OLD.id);
    ELSE
      PERFORM private.assert_payment_consistent(NEW.id);
    END IF;
  ELSE
    IF TG_OP <> 'DELETE' THEN
      PERFORM private.assert_payment_consistent(NEW.payment_id);
    END IF;
    IF TG_OP <> 'INSERT' THEN
      PERFORM private.assert_payment_consistent(OLD.payment_id);
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION payments_assert_consistency(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.payments_assert_consistency() IS 'DEFERRABLE INITIALLY DEFERRED CONSTRAINT TRIGGER on public.payments and public.payment_tenders: at COMMIT, re-checks every payment touched by the transaction through private.assert_payment_consistent. A CHECK cannot read other rows, so the tender sum, the change and the one-restaurant rule live here.';


--
-- Name: produce_preparation(uuid, numeric, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.produce_preparation(p_ingredient_id uuid, p_quantity numeric, p_location_id uuid DEFAULT NULL::uuid, p_lot_code text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  c_fn constant text := 'produce_preparation';
  v_caller    record;
  v_item      public.ingredients%ROWTYPE;
  v_recipe    public.recipes%ROWTYPE;
  v_loc       uuid;
  v_batch     uuid := gen_random_uuid();
  v_req       record;
  v_shortages jsonb;
  v_taken     jsonb;
  v_consumed  jsonb := '[]'::jsonb;
  v_total     numeric := 0;
  v_unit      numeric;
  v_expires   date;
  v_code      text;
  v_lot       uuid;
BEGIN
  SELECT * INTO v_caller FROM private.inventory_caller(c_fn, ARRAY['admin', 'kitchen']);

  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RAISE EXCEPTION '%: p_quantity must be positive', c_fn USING ERRCODE = '22023';
  END IF;

  -- No lock yet: the preparation is locked together with its inputs below,
  -- in one id-ordered statement, so it queues behind consume_order_stock
  -- (which locks every ingredient in id order) instead of deadlocking.
  SELECT * INTO v_item FROM public.ingredients i
   WHERE i.id = p_ingredient_id AND i.restaurant_id = v_caller.restaurant_id;
  IF v_item.id IS NULL THEN
    RAISE EXCEPTION '%: preparation % not found', c_fn, p_ingredient_id USING ERRCODE = 'P0002';
  END IF;
  IF v_item.kind <> 'prep' THEN
    RAISE EXCEPTION '%: % is not a preparation', c_fn, v_item.name USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_recipe FROM public.recipes r WHERE r.ingredient_id = v_item.id;
  IF v_recipe.id IS NULL OR NOT EXISTS (SELECT 1 FROM public.recipe_ingredients ri WHERE ri.recipe_id = v_recipe.id) THEN
    RAISE EXCEPTION '%: % has no formula', c_fn, v_item.name USING ERRCODE = 'P0001';
  END IF;

  v_loc := private.inventory_location(c_fn, v_caller.restaurant_id, p_location_id);

  -- Lock the preparation and its inputs in one id-ordered statement, then
  -- check every requirement before writing anything.
  PERFORM 1 FROM public.ingredients i
   WHERE i.id = v_item.id
      OR i.id IN (SELECT ri.ingredient_id FROM public.recipe_ingredients ri WHERE ri.recipe_id = v_recipe.id)
   ORDER BY i.id
   FOR UPDATE;
  SELECT * INTO v_item FROM public.ingredients i WHERE i.id = v_item.id;

  SELECT jsonb_agg(jsonb_build_object(
           'ingredient_id', q.ingredient_id, 'name', q.name, 'unit', q.unit,
           'required', q.required, 'available', q.available,
           'missing', (q.required - q.available)::numeric(14,3)) ORDER BY q.name)
    INTO v_shortages
    FROM (
      SELECT i.id AS ingredient_id, i.name, i.unit,
             (ri.quantity * p_quantity / v_recipe.yield_quantity)::numeric(14,3) AS required,
             COALESCE((SELECT sum(l.quantity) FROM public.inventory_lots l
                        WHERE l.ingredient_id = i.id AND l.location_id = v_loc AND l.quantity > 0), 0)::numeric(14,3) AS available
        FROM public.recipe_ingredients ri
        JOIN public.ingredients i ON i.id = ri.ingredient_id
       WHERE ri.recipe_id = v_recipe.id
    ) q
   WHERE q.required > q.available;

  IF v_shortages IS NOT NULL THEN
    RAISE EXCEPTION '%: insufficient stock: %', c_fn,
      (SELECT string_agg((s->>'name') || ' (missing ' || (s->>'missing') || ' ' || (s->>'unit') || ')', ', ')
         FROM jsonb_array_elements(v_shortages) s)
      USING ERRCODE = 'P0001', DETAIL = v_shortages::text;
  END IF;

  FOR v_req IN
    SELECT i.id, i.name, (ri.quantity * p_quantity / v_recipe.yield_quantity)::numeric(14,3) AS required
      FROM public.recipe_ingredients ri
      JOIN public.ingredients i ON i.id = ri.ingredient_id
     WHERE ri.recipe_id = v_recipe.id
     ORDER BY i.id
  LOOP
    CONTINUE WHEN v_req.required <= 0;
    v_taken := private.inventory_take(v_caller.restaurant_id, v_req.id, v_loc, v_req.required, 'production_consume',
                                      'production_batch', v_batch, v_caller.profile_id, false, NULL, p_notes);
    v_total := v_total + (v_taken->>'total_cost')::numeric;
    v_consumed := v_consumed || jsonb_build_object(
      'ingredient_id', v_req.id, 'name', v_req.name, 'quantity', v_req.required,
      'total_cost', round((v_taken->>'total_cost')::numeric, 4));
    PERFORM private.inventory_sync_stock(v_req.id);
  END LOOP;

  v_unit := round(v_total / p_quantity, 4);
  v_expires := CASE WHEN v_item.shelf_life_days IS NOT NULL THEN current_date + v_item.shelf_life_days END;
  v_code := COALESCE(NULLIF(btrim(p_lot_code), ''), 'PB-' || to_char(now(), 'YYYYMMDD-HH24MISS'));

  PERFORM private.inventory_average_cost(v_item.id, p_quantity, v_unit);
  v_lot := private.inventory_put(v_caller.restaurant_id, v_item.id, v_loc, p_quantity, v_unit, v_code, v_expires,
                                 now(), 'production_output', 'production_batch', v_batch,
                                 v_caller.profile_id, NULL, p_notes);
  PERFORM private.inventory_sync_stock(v_item.id);

  INSERT INTO public.production_batches
    (id, restaurant_id, ingredient_id, location_id, quantity, lot_id, unit_cost, total_cost, expires_on, notes, created_by)
  VALUES (v_batch, v_caller.restaurant_id, v_item.id, v_loc, p_quantity, v_lot, v_unit, v_total, v_expires,
          p_notes, v_caller.profile_id);

  RETURN jsonb_build_object(
    'batch_id', v_batch,
    'lot_id', v_lot,
    'lot_code', v_code,
    'ingredient_id', v_item.id,
    'location_id', v_loc,
    'quantity', p_quantity::numeric(14,3),
    'unit_cost', v_unit::numeric(14,4),
    'total_cost', round(v_total, 4),
    'expires_on', v_expires,
    'consumed', v_consumed
  );
END;
$$;


--
-- Name: FUNCTION produce_preparation(p_ingredient_id uuid, p_quantity numeric, p_location_id uuid, p_lot_code text, p_notes text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.produce_preparation(p_ingredient_id uuid, p_quantity numeric, p_location_id uuid, p_lot_code text, p_notes text) IS 'Produces p_quantity of a preparation at a location (NULL = default), admin or kitchen. Consumes each formula line x (p_quantity / yield_quantity) FEFO (production_consume), creates an output lot (p_lot_code or PB-YYYYMMDD-HH24MISS, expires_on = today + shelf_life_days) with unit_cost = consumed cost / p_quantity, updates the weighted-average cost and records a production_batches row. Insufficient stock raises P0001 naming every short item (DETAIL = jsonb shortages) and writes nothing. Returns {batch_id, lot_id, lot_code, ingredient_id, location_id, quantity, unit_cost, total_cost, expires_on, consumed:[{ingredient_id, name, quantity, total_cost}]}.';


--
-- Name: receive_purchase_order(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.receive_purchase_order(p_purchase_order_id uuid, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  c_fn constant text := 'receive_purchase_order';
  v_caller  record;
  v_po      public.purchase_orders%ROWTYPE;
  v_line    jsonb;
  v_pol     public.purchase_order_lines%ROWTYPE;
  v_id      uuid;
  v_qty     numeric;
  v_cost    numeric;
  v_expires date;
  v_seen    uuid[] := '{}';
  v_total   numeric := 0;
  v_status  text;
BEGIN
  SELECT * INTO v_caller FROM private.inventory_caller(c_fn, ARRAY['admin']);

  SELECT * INTO v_po FROM public.purchase_orders po
   WHERE po.id = p_purchase_order_id AND po.restaurant_id = v_caller.restaurant_id
   FOR UPDATE;
  IF v_po.id IS NULL THEN
    RAISE EXCEPTION '%: purchase order % not found', c_fn, p_purchase_order_id USING ERRCODE = 'P0002';
  END IF;
  IF v_po.status NOT IN ('ordered', 'partially_received') THEN
    RAISE EXCEPTION '%: purchase order % is %', c_fn, v_po.number, v_po.status USING ERRCODE = 'P0001';
  END IF;
  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION '%: p_lines must be a non-empty array', c_fn USING ERRCODE = '22023';
  END IF;

  -- Lock every ingredient of the order up front, in id order, instead of in
  -- the order the caller listed the lines, so concurrent stock writers queue.
  PERFORM 1 FROM public.ingredients i
   WHERE i.id IN (SELECT l.ingredient_id FROM public.purchase_order_lines l
                   WHERE l.purchase_order_id = v_po.id)
   ORDER BY i.id
   FOR UPDATE;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    BEGIN
      v_id := (v_line->>'line_id')::uuid;
      v_qty := (v_line->>'quantity')::numeric;
      v_cost := (v_line->>'unit_cost')::numeric;
      v_expires := (v_line->>'expires_on')::date;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION '%: invalid receipt line %', c_fn, v_line USING ERRCODE = '22023';
    END;
    IF v_id IS NULL OR v_qty IS NULL OR v_qty <= 0 OR (v_cost IS NOT NULL AND v_cost < 0) THEN
      RAISE EXCEPTION '%: each line needs line_id and a positive quantity', c_fn USING ERRCODE = '22023';
    END IF;
    IF v_id = ANY (v_seen) THEN
      RAISE EXCEPTION '%: line % appears twice', c_fn, v_id USING ERRCODE = '22023';
    END IF;
    v_seen := v_seen || v_id;

    SELECT * INTO v_pol FROM public.purchase_order_lines l
     WHERE l.id = v_id AND l.purchase_order_id = v_po.id
     FOR UPDATE;
    IF v_pol.id IS NULL THEN
      RAISE EXCEPTION '%: line % not found', c_fn, v_id USING ERRCODE = 'P0002';
    END IF;
    IF v_pol.received_quantity + v_qty > v_pol.quantity THEN
      RAISE EXCEPTION '%: receiving % exceeds the pending quantity %', c_fn, v_qty,
        v_pol.quantity - v_pol.received_quantity USING ERRCODE = 'P0001';
    END IF;

    v_cost := COALESCE(v_cost, v_pol.unit_cost);
    PERFORM private.inventory_average_cost(v_pol.ingredient_id, v_qty, v_cost);
    PERFORM private.inventory_put(v_caller.restaurant_id, v_pol.ingredient_id, v_po.location_id, v_qty, v_cost,
                                  v_line->>'lot_code', v_expires, now(), 'purchase',
                                  'purchase_order', v_po.id, v_caller.profile_id, NULL, NULL);
    UPDATE public.purchase_order_lines SET received_quantity = received_quantity + v_qty WHERE id = v_pol.id;
    PERFORM private.inventory_sync_stock(v_pol.ingredient_id);
    v_total := v_total + v_qty * v_cost;
  END LOOP;

  v_status := CASE WHEN EXISTS (SELECT 1 FROM public.purchase_order_lines l
                                 WHERE l.purchase_order_id = v_po.id AND l.received_quantity < l.quantity)
                   THEN 'partially_received' ELSE 'received' END;
  UPDATE public.purchase_orders
     SET status = v_status,
         received_at = CASE WHEN v_status = 'received' THEN now() ELSE received_at END
   WHERE id = v_po.id;

  RETURN jsonb_build_object(
    'purchase_order_id', v_po.id,
    'status', v_status,
    'received_lines', jsonb_array_length(p_lines),
    'total_cost', round(v_total, 4)
  );
END;
$$;


--
-- Name: FUNCTION receive_purchase_order(p_purchase_order_id uuid, p_lines jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.receive_purchase_order(p_purchase_order_id uuid, p_lines jsonb) IS 'Receives goods for an ordered / partially_received purchase order (admin). p_lines = [{line_id, quantity > 0, unit_cost? (default line cost), lot_code?, expires_on?}] in base units, at the order location. Writes purchase movements, updates the weighted-average ingredients.cost and received_quantity; over-receipt is P0001. Status becomes received (received_at = now()) when every line is complete, else partially_received. Returns {purchase_order_id, status, received_lines, total_cost}.';


--
-- Name: recipe_ingredients_cycle_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recipe_ingredients_cycle_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_output uuid;
  v_rid    uuid;
BEGIN
  SELECT r.ingredient_id, r.restaurant_id INTO v_output, v_rid
    FROM public.recipes r WHERE r.id = NEW.recipe_id;

  IF v_rid IS DISTINCT FROM NEW.restaurant_id THEN
    RAISE EXCEPTION 'recipe % not found', NEW.recipe_id USING ERRCODE = 'P0002';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.ingredients i
                  WHERE i.id = NEW.ingredient_id AND i.restaurant_id = v_rid) THEN
    RAISE EXCEPTION 'ingredient % not found', NEW.ingredient_id USING ERRCODE = 'P0002';
  END IF;

  IF v_output IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.ingredient_id = v_output THEN
    RAISE EXCEPTION 'a preparation cannot use itself' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    WITH RECURSIVE reach(ingredient_id) AS (
      SELECT NEW.ingredient_id
      UNION
      SELECT ri.ingredient_id
        FROM reach
        JOIN public.recipes r ON r.ingredient_id = reach.ingredient_id
        JOIN public.recipe_ingredients ri ON ri.recipe_id = r.id
    )
    SELECT 1 FROM reach WHERE reach.ingredient_id = v_output
  ) THEN
    RAISE EXCEPTION 'formula cycle: % already uses this preparation', NEW.ingredient_id
      USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION recipe_ingredients_cycle_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recipe_ingredients_cycle_guard() IS 'AFTER INSERT / UPDATE on public.recipe_ingredients: the recipe and the line ingredient must belong to the line restaurant_id (P0002); the line ingredient must belong to the recipe restaurant (P0002); a preparation formula may not use itself or any preparation that (transitively) uses it (22023).';


--
-- Name: recipes_target_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recipes_target_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_kind text;
  v_rid  uuid;
BEGIN
  IF NEW.ingredient_id IS NOT NULL THEN
    SELECT i.kind, i.restaurant_id INTO v_kind, v_rid
      FROM public.ingredients i WHERE i.id = NEW.ingredient_id;
    IF v_rid IS DISTINCT FROM NEW.restaurant_id THEN
      RAISE EXCEPTION 'formula output % not found', NEW.ingredient_id USING ERRCODE = 'P0002';
    END IF;
    IF v_kind <> 'prep' THEN
      RAISE EXCEPTION 'formula output must be a preparation' USING ERRCODE = '22023';
    END IF;
  ELSIF NEW.dish_id IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM public.dishes d WHERE d.id = NEW.dish_id AND d.restaurant_id = NEW.restaurant_id) THEN
    RAISE EXCEPTION 'dish % not found', NEW.dish_id USING ERRCODE = 'P0002';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION recipes_target_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recipes_target_guard() IS 'BEFORE INSERT / UPDATE on public.recipes: the target dish or preparation must belong to the recipe restaurant (P0002) and a preparation target must have kind = prep (22023).';


--
-- Name: register_summary(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_summary(p_cash_register_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_caller_tenant   uuid;
  v_caller_role     text;

  v_visible_count   bigint := 0;
  v_array_len       integer;

  v_initial_cash    bigint := 0;
  v_payments_count  bigint := 0;
  v_total_billed    bigint := 0;
  v_total_tips      bigint := 0;
  v_total_sales     bigint := 0;
  v_total_change    bigint := 0;

  v_cash_deposits    bigint := 0;
  v_cash_withdrawals bigint := 0;
  v_cash_tender_total bigint := 0;
  v_expected_cash    bigint := 0;
  v_tips_payout      bigint := 0;
  v_after_tips       bigint := 0;

  v_methods         jsonb;
  v_legacy          jsonb;

  v_ids uuid[];
BEGIN
  -- 1. Caller resolution. delivery_operator is admitted (read-only) so the
  -- operator can read the same summary the cashier / admin close screen
  -- shows. The summary is a SECURITY INVOKER read; it does not write.
  v_caller_tenant := private.current_restaurant_id();
  v_caller_role   := private.current_app_role();

  IF v_caller_tenant IS NULL OR v_caller_role IS NULL THEN
    RAISE EXCEPTION 'register_summary: the caller has no profile'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_caller_role NOT IN ('cashier', 'admin', 'delivery_operator') THEN
    RAISE EXCEPTION 'register_summary: only cashier, admin or delivery_operator may read the summary'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 2. Input validation.
  IF p_cash_register_ids IS NULL THEN
    RAISE EXCEPTION 'register_summary: p_cash_register_ids must not be NULL'
      USING ERRCODE = '22023';
  END IF;

  v_array_len := array_length(p_cash_register_ids, 1);
  IF v_array_len IS NULL OR v_array_len = 0 THEN
    RAISE EXCEPTION 'register_summary: p_cash_register_ids must be a non-empty array'
      USING ERRCODE = '22023';
  END IF;

  IF v_array_len > 100 THEN
    RAISE EXCEPTION 'register_summary: p_cash_register_ids accepts at most 100 entries'
      USING ERRCODE = '22023';
  END IF;

  IF (SELECT count(v) FROM (
         SELECT v FROM unnest(p_cash_register_ids) v
       ) s) <> v_array_len THEN
    RAISE EXCEPTION 'register_summary: p_cash_register_ids must not contain NULL'
      USING ERRCODE = '22023';
  END IF;

  IF (SELECT count(*) FROM (
         SELECT v FROM unnest(p_cash_register_ids) v
       ) s) <> (SELECT count(DISTINCT v) FROM unnest(p_cash_register_ids) v) THEN
    RAISE EXCEPTION 'register_summary: p_cash_register_ids must not contain duplicates'
      USING ERRCODE = '22023';
  END IF;

  SELECT count(*) INTO v_visible_count
    FROM public.cash_registers
   WHERE id = ANY (p_cash_register_ids);

  IF v_visible_count <> v_array_len THEN
    RAISE EXCEPTION 'register_summary: cash register(s) not found'
      USING ERRCODE = 'P0002';
  END IF;

  v_ids := ARRAY(SELECT DISTINCT v FROM unnest(p_cash_register_ids) v);

  SELECT
      coalesce(round(SUM(cr.initial_cash))::bigint, 0)
    INTO v_initial_cash
    FROM public.cash_registers cr
   WHERE cr.id = ANY (v_ids);

  SELECT
      count(*),
      coalesce(sum(p.amount_due), 0)::bigint,
      coalesce(sum(p.tip_amount),  0)::bigint,
      coalesce(sum(p.change_given), 0)::bigint
    INTO v_payments_count, v_total_billed, v_total_tips, v_total_change
    FROM public.payments p
   WHERE p.cash_register_id = ANY (v_ids);

  SELECT coalesce(sum(t.amount), 0)::bigint
    INTO v_total_sales
    FROM public.payment_tenders t
    JOIN public.payments p ON p.id = t.payment_id
   WHERE p.cash_register_id = ANY (v_ids);

  SELECT
      coalesce(round(SUM(CASE WHEN ct.type = 'deposit'    THEN ct.amount ELSE 0 END))::bigint, 0),
      coalesce(round(SUM(CASE WHEN ct.type = 'withdrawal' THEN ct.amount ELSE 0 END))::bigint, 0)
    INTO v_cash_deposits, v_cash_withdrawals
    FROM public.cash_transactions ct
   WHERE ct.cash_register_id = ANY (v_ids);

  SELECT coalesce(sum(t.amount), 0)::bigint
    INTO v_cash_tender_total
    FROM public.payment_tenders t
    JOIN public.payments p ON p.id = t.payment_id
   WHERE p.cash_register_id = ANY (v_ids)
     AND t.method_kind = 'cash';

  v_expected_cash   := v_initial_cash + v_cash_tender_total + v_cash_deposits - v_cash_withdrawals;
  v_tips_payout     := v_total_tips;
  v_after_tips      := v_expected_cash - v_tips_payout;

  SELECT coalesce(jsonb_agg(row_to_json(m) ORDER BY m.sort_order, m.name), '[]'::jsonb)
    INTO v_methods
    FROM (
      SELECT
          cat.id            AS payment_method_id,
          cat.code          AS code,
          cat.name          AS name,
          cat.kind          AS kind,
          cat.sort_order    AS sort_order,
          cat.is_active     AS is_active,
          coalesce(agg.total, 0)::bigint       AS total,
          coalesce(agg.tenders_count, 0)::bigint AS tenders_count
        FROM public.payment_methods cat
        LEFT JOIN (
          SELECT t.payment_method_id,
                 sum(t.amount)::bigint AS total,
                 count(*)::bigint      AS tenders_count
            FROM public.payment_tenders t
            JOIN public.payments p ON p.id = t.payment_id
           WHERE p.cash_register_id = ANY (v_ids)
           GROUP BY t.payment_method_id
        ) agg ON agg.payment_method_id = cat.id
       WHERE cat.restaurant_id = v_caller_tenant
    ) m;

  SELECT jsonb_build_object(
      'payments_count', count(*)::bigint,
      'total',         coalesce(round(SUM(pt.amount))::bigint,       0),
      'tips',          coalesce(round(SUM(pt.tip_amount))::bigint,   0),
      'change',        coalesce(round(SUM(pt.cash_change))::bigint,  0),
      'by_method',     (
        SELECT coalesce(jsonb_object_agg(method, total), '{}'::jsonb)
          FROM (
            SELECT pt2.method,
                   round(SUM(pt2.amount))::bigint AS total
              FROM public.payment_transactions pt2
             WHERE pt2.cash_register_id = ANY (v_ids)
             GROUP BY pt2.method
          ) bm
      )
    )
    INTO v_legacy
    FROM public.payment_transactions pt
   WHERE pt.cash_register_id = ANY (v_ids);

  v_legacy := coalesce(v_legacy, jsonb_build_object(
    'payments_count', 0,
    'total',         0,
    'tips',          0,
    'change',        0,
    'by_method',     '{}'::jsonb
  ));

  RETURN jsonb_build_object(
    'registers_count',         v_array_len::bigint,
    'initial_cash',            v_initial_cash,
    'payments_count',          v_payments_count,
    'total_billed',            v_total_billed,
    'total_tips',              v_total_tips,
    'total_sales',             v_total_sales,
    'total_change',            v_total_change,
    'methods',                 v_methods,
    'cash_deposits',           v_cash_deposits,
    'cash_withdrawals',        v_cash_withdrawals,
    'expected_cash',           v_expected_cash,
    'tips_payout',             v_tips_payout,
    'expected_cash_after_tips', v_after_tips,
    'legacy',                  v_legacy
  );
END;
$$;


--
-- Name: FUNCTION register_summary(p_cash_register_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.register_summary(p_cash_register_ids uuid[]) IS 'Server-side aggregation for the close-register screen and the admin reports. SECURITY INVOKER (rely on RLS), STABLE, search_path pinned. Caller resolution through private.current_restaurant_id() / private.current_app_role() (42501 for non-cashier/admin/delivery_operator). Input validation: NULL/empty/duplicates/>100 ids raise 22023. Visibility: any id the caller''s RLS cannot see raises P0002 (other tenant or missing). The methods array is a LEFT JOIN from the tenant catalog so zero-sale and inactive methods still appear (sort_order, name). expected_cash = round(initial_cash) + cash_tender_amounts + deposits - withdrawals, the same formula pay_order uses for drawer_cash_before on a single open register (equality pinned by 090). tips are paid out to waiters at close, so tips_payout = total_tips (all tips, any method) and expected_cash_after_tips = expected_cash - tips_payout (may be negative, not clamped). Legacy section reads public.payment_transactions (zeros when none) and is reported separately: legacy rows do NOT enter expected_cash. Money as bigint (whole COP pesos); numeric(10,2) columns are rounded with Postgres half-up rounding.';


--
-- Name: save_formula(text, uuid, numeric, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_formula(p_target_type text, p_target_id uuid, p_yield_quantity numeric, p_lines jsonb, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  c_fn constant text := 'save_formula';
  v_caller  record;
  v_kind    text;
  v_recipe  uuid;
  v_line    jsonb;
  v_ing     uuid;
  v_qty     numeric;
  v_seen    uuid[] := '{}';
  v_total   numeric;
BEGIN
  SELECT * INTO v_caller FROM private.inventory_caller(c_fn, ARRAY['admin']);

  -- Serialize formula saves per tenant so two concurrent saves (A uses B,
  -- B uses A) cannot both pass the cycle check.
  PERFORM pg_advisory_xact_lock(hashtext('save_formula:' || v_caller.restaurant_id::text));

  IF p_target_type IS NULL OR p_target_type NOT IN ('dish', 'prep') THEN
    RAISE EXCEPTION '%: p_target_type must be dish or prep', c_fn USING ERRCODE = '22023';
  END IF;
  IF p_yield_quantity IS NULL OR p_yield_quantity <= 0 THEN
    RAISE EXCEPTION '%: p_yield_quantity must be positive', c_fn USING ERRCODE = '22023';
  END IF;
  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array'
     OR jsonb_array_length(p_lines) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION '%: p_lines must be an array of 1..200 lines', c_fn USING ERRCODE = '22023';
  END IF;

  IF p_target_type = 'dish' THEN
    IF NOT EXISTS (SELECT 1 FROM public.dishes d WHERE d.id = p_target_id AND d.restaurant_id = v_caller.restaurant_id) THEN
      RAISE EXCEPTION '%: dish % not found', c_fn, p_target_id USING ERRCODE = 'P0002';
    END IF;
    SELECT r.id INTO v_recipe FROM public.recipes r WHERE r.dish_id = p_target_id FOR UPDATE;
  ELSE
    SELECT i.kind INTO v_kind FROM public.ingredients i
     WHERE i.id = p_target_id AND i.restaurant_id = v_caller.restaurant_id;
    IF v_kind IS NULL THEN
      RAISE EXCEPTION '%: preparation % not found', c_fn, p_target_id USING ERRCODE = 'P0002';
    END IF;
    IF v_kind <> 'prep' THEN
      RAISE EXCEPTION '%: the formula output must be a preparation', c_fn USING ERRCODE = '22023';
    END IF;
    SELECT r.id INTO v_recipe FROM public.recipes r WHERE r.ingredient_id = p_target_id FOR UPDATE;
  END IF;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    BEGIN
      v_ing := (v_line->>'ingredient_id')::uuid;
      v_qty := (v_line->>'quantity')::numeric;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION '%: each line needs a uuid ingredient_id and a numeric quantity', c_fn USING ERRCODE = '22023';
    END;
    IF v_ing IS NULL OR v_qty IS NULL OR v_qty <= 0 THEN
      RAISE EXCEPTION '%: each line needs an ingredient_id and a positive quantity', c_fn USING ERRCODE = '22023';
    END IF;
    IF v_ing = ANY (v_seen) THEN
      RAISE EXCEPTION '%: ingredient % appears twice', c_fn, v_ing USING ERRCODE = '22023';
    END IF;
    IF p_target_type = 'prep' AND v_ing = p_target_id THEN
      RAISE EXCEPTION '%: a preparation cannot use itself', c_fn USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.ingredients i WHERE i.id = v_ing AND i.restaurant_id = v_caller.restaurant_id) THEN
      RAISE EXCEPTION '%: ingredient % not found', c_fn, v_ing USING ERRCODE = 'P0002';
    END IF;
    v_seen := v_seen || v_ing;
  END LOOP;

  IF v_recipe IS NULL THEN
    INSERT INTO public.recipes (restaurant_id, dish_id, ingredient_id, yield_quantity, notes)
    VALUES (v_caller.restaurant_id,
            CASE WHEN p_target_type = 'dish' THEN p_target_id END,
            CASE WHEN p_target_type = 'prep' THEN p_target_id END,
            p_yield_quantity, p_notes)
    RETURNING id INTO v_recipe;
  ELSE
    UPDATE public.recipes SET yield_quantity = p_yield_quantity, notes = p_notes WHERE id = v_recipe;
    DELETE FROM public.recipe_ingredients WHERE recipe_id = v_recipe;
  END IF;

  -- The cycle guard on recipe_ingredients raises 22023 here and rolls back the
  -- whole call, so the previous formula stays intact.
  INSERT INTO public.recipe_ingredients (restaurant_id, recipe_id, ingredient_id, quantity)
  SELECT v_caller.restaurant_id, v_recipe, (l->>'ingredient_id')::uuid, (l->>'quantity')::numeric
    FROM jsonb_array_elements(p_lines) l;

  SELECT COALESCE(sum(ri.quantity * COALESCE(i.cost, 0)), 0) INTO v_total
    FROM public.recipe_ingredients ri JOIN public.ingredients i ON i.id = ri.ingredient_id
   WHERE ri.recipe_id = v_recipe;

  RETURN jsonb_build_object(
    'recipe_id', v_recipe,
    'target_type', p_target_type,
    'target_id', p_target_id,
    'yield_quantity', p_yield_quantity::numeric(14,3),
    'lines_count', jsonb_array_length(p_lines),
    'total_cost', round(v_total, 4),
    'unit_cost', round(v_total / p_yield_quantity, 4)
  );
END;
$$;


--
-- Name: FUNCTION save_formula(p_target_type text, p_target_id uuid, p_yield_quantity numeric, p_lines jsonb, p_notes text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.save_formula(p_target_type text, p_target_id uuid, p_yield_quantity numeric, p_lines jsonb, p_notes text) IS 'Atomically replaces the formula of a dish (p_target_type = dish) or a preparation (prep, output kind must be prep), admin only. p_lines = [{ingredient_id, quantity > 0}] (1..200, no duplicates, tenant items). Rejects self-reference and cycles (22023), foreign targets / items (P0002). Returns {recipe_id, target_type, target_id, yield_quantity, lines_count, total_cost, unit_cost = total_cost / yield_quantity} at current ingredients.cost.';


