--
-- Name: set_delivery_status(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_delivery_status(p_order_id uuid, p_action text, p_courier_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_caller_tenant   uuid;
  v_caller_role     text;

  v_delivery        public.order_deliveries%ROWTYPE;
  v_order           public.orders%ROWTYPE;
  v_current_state   text;
  v_target_state    text;
  v_courier         public.couriers%ROWTYPE;
  v_reason_text     text;

  v_allowed_states  text[];
  v_kitchen_allowed boolean := false;
  v_caller_allowed  boolean := false;

  v_now             timestamptz := now();
BEGIN
  -- 1. Caller resolution.
  v_caller_tenant := private.current_restaurant_id();
  v_caller_role   := private.current_app_role();

  IF v_caller_tenant IS NULL OR v_caller_role IS NULL THEN
    RAISE EXCEPTION 'set_delivery_status: the caller has no profile'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 2. Lock the delivery row in the caller's tenant.
  SELECT od.* INTO v_delivery
    FROM public.order_deliveries od
   WHERE od.order_id = p_order_id
     AND od.restaurant_id = v_caller_tenant
     FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'set_delivery_status: delivery for order % not found', p_order_id
      USING ERRCODE = 'P0002';
  END IF;

  v_current_state := v_delivery.delivery_status;

  -- 3. Action dispatch.
  IF p_action NOT IN ('start_preparing', 'mark_ready', 'dispatch', 'deliver', 'fail', 'cancel') THEN
    RAISE EXCEPTION 'set_delivery_status: unknown action ''%''', p_action
      USING ERRCODE = '22023';
  END IF;

  -- role/action matrix.
  IF p_action IN ('start_preparing', 'mark_ready') THEN
    v_kitchen_allowed := v_caller_role IN ('kitchen', 'delivery_operator', 'admin');
    v_caller_allowed  := v_kitchen_allowed;
  ELSE
    v_caller_allowed := v_caller_role IN ('delivery_operator', 'admin');
  END IF;

  IF NOT v_caller_allowed THEN
    RAISE EXCEPTION 'set_delivery_status: role ''%'' may not perform ''%''',
      v_caller_role, p_action
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 4. State machine.
  IF p_action = 'start_preparing' THEN
    v_allowed_states := ARRAY['received'];
    v_target_state   := 'preparing';
  ELSIF p_action = 'mark_ready' THEN
    v_allowed_states := ARRAY['received', 'preparing'];
    v_target_state   := 'ready';
  ELSIF p_action = 'dispatch' THEN
    v_allowed_states := ARRAY['ready', 'failed'];
    v_target_state   := 'out_for_delivery';
  ELSIF p_action = 'deliver' THEN
    v_allowed_states := ARRAY['out_for_delivery'];
    v_target_state   := 'delivered';
  ELSIF p_action = 'fail' THEN
    v_allowed_states := ARRAY['out_for_delivery'];
    v_target_state   := 'failed';
  ELSIF p_action = 'cancel' THEN
    v_allowed_states := ARRAY['received', 'preparing', 'ready', 'failed'];
    v_target_state   := 'cancelled';
  END IF;

  -- Same-state replays: P0001 with a clear message naming the current state.
  -- Easier to reason about in the UI than a silent no-op.
  IF v_current_state = v_target_state THEN
    RAISE EXCEPTION 'set_delivery_status: delivery for order % is already in state ''%''',
      p_order_id, v_current_state
      USING ERRCODE = 'P0001';
  END IF;

  IF NOT (v_current_state = ANY (v_allowed_states)) THEN
    RAISE EXCEPTION 'set_delivery_status: action ''%'' is not allowed from state ''%'' (allowed: %)',
      p_action, v_current_state, array_to_string(v_allowed_states, ', ')
      USING ERRCODE = 'P0001';
  END IF;

  -- 5. Per-action validation.
  IF p_action = 'fail' THEN
    v_reason_text := btrim(coalesce(p_reason, ''));
    IF v_reason_text = '' THEN
      RAISE EXCEPTION 'set_delivery_status: fail requires a non-empty reason'
        USING ERRCODE = '22023';
    END IF;
    IF length(v_reason_text) > 200 THEN
      RAISE EXCEPTION 'set_delivery_status: fail reason must be <= 200 characters'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  IF p_action = 'dispatch' THEN
    IF p_courier_id IS NULL THEN
      RAISE EXCEPTION 'set_delivery_status: dispatch requires p_courier_id'
        USING ERRCODE = '22023';
    END IF;

    SELECT co.* INTO v_courier
      FROM public.couriers co
     WHERE co.id = p_courier_id
       AND co.restaurant_id = v_caller_tenant;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'set_delivery_status: courier % not found', p_courier_id
        USING ERRCODE = 'P0002';
    END IF;

    IF NOT v_courier.is_active THEN
      RAISE EXCEPTION 'set_delivery_status: courier % is not active', p_courier_id
        USING ERRCODE = '22023';
    END IF;
  END IF;

  IF p_action = 'cancel' THEN
    -- Lock the order before looking for payments: pay_order holds this lock
    -- while it writes, so the check cannot pass and then lose to a payment
    -- committed in between (which would cancel a paid order).
    PERFORM 1 FROM public.orders o
      WHERE o.id = p_order_id
        AND o.restaurant_id = v_caller_tenant
        FOR UPDATE;

    -- Refuse to cancel an order that has a payment: refunds are out of scope.
    IF EXISTS (SELECT 1 FROM public.payments p WHERE p.order_id = p_order_id)
       OR EXISTS (SELECT 1 FROM public.orders o
                   WHERE o.id = p_order_id AND o.status = 'paid') THEN
      RAISE EXCEPTION 'set_delivery_status: order % already has a payment (refunds are out of scope)',
        p_order_id
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- 6. Writes.
  IF p_action = 'start_preparing' THEN
    UPDATE public.order_deliveries od
       SET delivery_status = 'preparing'
     WHERE od.order_id = p_order_id;
  ELSIF p_action = 'mark_ready' THEN
    UPDATE public.order_deliveries od
       SET delivery_status = 'ready'
     WHERE od.order_id = p_order_id;
  ELSIF p_action = 'dispatch' THEN
    UPDATE public.order_deliveries od
       SET delivery_status = 'out_for_delivery',
           courier_id     = v_courier.id,
           dispatched_at  = v_now,
           failure_reason = NULL
     WHERE od.order_id = p_order_id;
  ELSIF p_action = 'deliver' THEN
    UPDATE public.order_deliveries od
       SET delivery_status = 'delivered',
           delivered_at    = v_now
     WHERE od.order_id = p_order_id;
  ELSIF p_action = 'fail' THEN
    UPDATE public.order_deliveries od
       SET delivery_status = 'failed',
           failure_reason  = v_reason_text,
           failed_at       = v_now
     WHERE od.order_id = p_order_id;
  ELSIF p_action = 'cancel' THEN
    -- The order row is already locked by the payment check above. pay_order
    -- locks the order FOR UPDATE and never the delivery row, so a concurrent
    -- cancel + pay_order pair cannot form a cycle.
    UPDATE public.order_deliveries od
       SET delivery_status = 'cancelled',
           cancelled_at    = v_now
     WHERE od.order_id = p_order_id;

    UPDATE public.orders o
       SET status      = 'cancelled',
           updated_at  = v_now
     WHERE o.id = p_order_id
       AND o.restaurant_id = v_caller_tenant;
  END IF;

  -- 7. Response.
  SELECT od.* INTO v_delivery
    FROM public.order_deliveries od
   WHERE od.order_id = p_order_id;

  RETURN to_jsonb(v_delivery);
END;
$$;


--
-- Name: FUNCTION set_delivery_status(p_order_id uuid, p_action text, p_courier_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_delivery_status(p_order_id uuid, p_action text, p_courier_id uuid, p_reason text) IS 'Delivery lifecycle machine. SECURITY DEFINER (owner postgres). Locks the order_deliveries row FOR UPDATE; missing or foreign -> P0002. Action role matrix: start_preparing and mark_ready are open to kitchen / delivery_operator / admin; dispatch / deliver / fail / cancel are delivery_operator / admin only (else 42501). Transitions: start_preparing (received -> preparing), mark_ready (received|preparing -> ready), dispatch (ready|failed -> out_for_delivery; requires an ACTIVE courier of the tenant; clears failure_reason on re-dispatch), deliver (out_for_delivery -> delivered), fail (out_for_delivery -> failed; reason 1..200), cancel (received|preparing|ready|failed -> cancelled; REJECT P0001 if a public.payments row already exists; also sets orders.status = cancelled and cancels_at). Same-state replays raise P0001 (no silent no-op). Returns the updated order_deliveries row as jsonb.';


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION set_updated_at(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_updated_at() IS 'BEFORE UPDATE trigger: stamps NEW.updated_at = now(). Used by the delivery module tables (couriers, customers, customer_addresses, order_deliveries); the payment_methods table has its own per-table variant in 20261006100000.';


--
-- Name: split_order(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.split_order(p_parent_order_id uuid, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_caller_tenant   uuid;
  v_caller_role     text;

  v_parent          public.orders%ROWTYPE;
  v_child_id        uuid;

  v_item_count      integer := 0;
  v_item            jsonb;
  v_line_no         integer := 0;
  v_item_id         uuid;
  v_item_qty        integer;

  v_pending_item_id  uuid[]    := '{}'::uuid[];
  v_pending_quantity integer[] := '{}'::integer[];

  v_remaining jsonb;

  v_parent_item public.order_items%ROWTYPE;

  v_child_subtotal bigint;
  v_child_tax      bigint;
  v_child_tip      bigint;
  v_child_total    bigint;
  v_child_tax_pct  numeric;
  v_child_tip_pct  numeric;

  v_parent_subtotal bigint;
  v_parent_tax      bigint;
  v_parent_tip      bigint;
  v_parent_total    bigint;
  v_parent_tax_pct  numeric;
  v_parent_tip_pct  numeric;

  v_i integer;
BEGIN
  -- 1. Caller resolution.
  v_caller_tenant := private.current_restaurant_id();
  v_caller_role   := private.current_app_role();

  IF v_caller_tenant IS NULL OR v_caller_role IS NULL THEN
    RAISE EXCEPTION 'split_order: the caller has no profile'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_caller_role NOT IN ('cashier', 'admin') THEN
    RAISE EXCEPTION 'split_order: only cashier or admin may split an order'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 2. Input validation.
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'split_order: p_items must be a JSON array'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'split_order: p_items must be a non-empty JSON array'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_array_length(p_items) > 50 THEN
    RAISE EXCEPTION 'split_order: p_items accepts at most 50 lines'
      USING ERRCODE = '22023';
  END IF;

  v_item_count := jsonb_array_length(p_items);

  FOR v_line_no IN 1..v_item_count LOOP
    v_item := p_items -> (v_line_no - 1);

    IF v_item IS NULL OR jsonb_typeof(v_item) <> 'object' THEN
      RAISE EXCEPTION 'split_order: item[%] must be a JSON object', v_line_no
        USING ERRCODE = '22023';
    END IF;

    IF NOT (v_item ? 'order_item_id') THEN
      RAISE EXCEPTION 'split_order: item[%] is missing order_item_id', v_line_no
        USING ERRCODE = '22023';
    END IF;

    BEGIN
      v_item_id := (v_item ->> 'order_item_id')::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'split_order: item[%].order_item_id is not a uuid', v_line_no
        USING ERRCODE = '22023';
    END;

    IF NOT (v_item ? 'quantity') THEN
      RAISE EXCEPTION 'split_order: item[%] is missing quantity', v_line_no
        USING ERRCODE = '22023';
    END IF;

    BEGIN
      v_item_qty := (v_item ->> 'quantity')::integer;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'split_order: item[%].quantity is not an integer', v_line_no
        USING ERRCODE = '22023';
    END;

    IF v_item_qty IS NULL OR v_item_qty < 1 THEN
      RAISE EXCEPTION 'split_order: item[%].quantity must be a positive integer', v_line_no
        USING ERRCODE = '22023';
    END IF;

    v_i := array_position(v_pending_item_id, v_item_id);
    IF v_i IS NOT NULL THEN
      RAISE EXCEPTION 'split_order: item[%].order_item_id duplicates item[%]',
        v_line_no, v_i
        USING ERRCODE = '22023';
    END IF;

    v_pending_item_id  := v_pending_item_id || v_item_id;
    v_pending_quantity := v_pending_quantity || v_item_qty;
  END LOOP;

  -- 3. Order.
  SELECT o.* INTO v_parent
    FROM public.orders o
   WHERE o.id = p_parent_order_id
     FOR UPDATE;

  IF NOT FOUND OR v_parent.restaurant_id <> v_caller_tenant THEN
    RAISE EXCEPTION 'split_order: order % not found', p_parent_order_id
      USING ERRCODE = 'P0002';
  END IF;

  -- CHANGE: reject delivery orders. A delivery order carries a snapshot of
  -- the customer / address in order_deliveries; splitting it would either
  -- double the delivery (one courier, two orders) or orphan a partial
  -- delivery with no destination. Refuse explicitly.
  IF v_parent.order_type = 'delivery' THEN
    RAISE EXCEPTION 'split_order: order % cannot be split (it is a delivery order)',
      p_parent_order_id
      USING ERRCODE = 'P0001';
  END IF;

  -- 4. Parent rules.
  IF v_parent.is_partial_order THEN
    RAISE EXCEPTION 'split_order: order % is itself a partial child (cannot be split further)',
      p_parent_order_id
      USING ERRCODE = 'P0001';
  END IF;

  IF v_parent.status NOT IN ('active', 'kitchen', 'delivered') THEN
    RAISE EXCEPTION 'split_order: order % cannot be split (status=%)',
      p_parent_order_id, v_parent.status
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (SELECT 1 FROM public.payments p WHERE p.order_id = p_parent_order_id) THEN
    RAISE EXCEPTION 'split_order: order % already has a payment', p_parent_order_id
      USING ERRCODE = 'P0001';
  END IF;

  -- 5. Items.
  v_remaining := '{}'::jsonb;

  FOR v_line_no IN 1..v_item_count LOOP
    v_item_id  := v_pending_item_id[v_line_no];
    v_item_qty := v_pending_quantity[v_line_no];

    SELECT oi.* INTO v_parent_item
      FROM public.order_items oi
     WHERE oi.id = v_item_id
       AND oi.order_id = p_parent_order_id
       AND oi.restaurant_id = v_caller_tenant;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'split_order: item[%] does not belong to the order', v_line_no
        USING ERRCODE = 'P0001';
    END IF;

    IF v_item_qty > v_parent_item.quantity THEN
      RAISE EXCEPTION 'split_order: item[%] quantity % exceeds the available quantity %',
        v_line_no, v_item_qty, v_parent_item.quantity
        USING ERRCODE = 'P0001';
    END IF;

    v_remaining := v_remaining || jsonb_build_object(
      v_item_id::text,
      to_jsonb(v_parent_item.quantity - v_item_qty)
    );
  END LOOP;

  -- 6. Move-all guard.
  SELECT count(*)::bigint
    INTO v_i
    FROM (
      SELECT (v_remaining ->> k.k)::int AS remaining
        FROM jsonb_object_keys(v_remaining) k(k)
       WHERE (v_remaining ->> k.k)::int > 0
      UNION ALL
      SELECT oi.quantity
        FROM public.order_items oi
       WHERE oi.order_id = p_parent_order_id
         AND NOT (v_remaining ? oi.id::text)
    ) s
   WHERE s.remaining > 0;

  IF v_i = 0 THEN
    RAISE EXCEPTION 'split_order: cannot move every item; pay the order instead'
      USING ERRCODE = 'P0001';
  END IF;

  -- 7. Child.
  INSERT INTO public.orders (
    restaurant_id, table_id, waiter_id, status,
    subtotal, tax, tax_percentage, tip, tip_percentage, total,
    total_discounts, is_partial_order, parent_order_id
  ) VALUES (
    v_caller_tenant, v_parent.table_id, v_parent.waiter_id, v_parent.status,
    0, 0, v_parent.tax_percentage, 0, v_parent.tip_percentage, 0,
    v_parent.total_discounts, true, p_parent_order_id
  )
  RETURNING id INTO v_child_id;

  -- 8. Move.
  FOR v_line_no IN 1..v_item_count LOOP
    v_item_id  := v_pending_item_id[v_line_no];
    v_item_qty := v_pending_quantity[v_line_no];

    SELECT oi.* INTO v_parent_item
      FROM public.order_items oi
     WHERE oi.id = v_item_id
       AND oi.order_id = p_parent_order_id
       AND oi.restaurant_id = v_caller_tenant
     FOR UPDATE;

    IF v_item_qty = v_parent_item.quantity THEN
      UPDATE public.order_items oi
         SET order_id = v_child_id
       WHERE oi.id = v_item_id;
    ELSE
      UPDATE public.order_items oi
         SET quantity = oi.quantity - v_item_qty
       WHERE oi.id = v_item_id;

      INSERT INTO public.order_items (
        order_id, dish_id, name, price, quantity, comments,
        status, added_at, restaurant_id, stock_consumed_at
      ) VALUES (
        v_child_id, v_parent_item.dish_id, v_parent_item.name, v_parent_item.price,
        v_item_qty, v_parent_item.comments, v_parent_item.status,
        v_parent_item.added_at, v_caller_tenant, v_parent_item.stock_consumed_at
      );
    END IF;
  END LOOP;

  -- 9. Recompute.
  SELECT subtotal, tax, tip, total, tax_percentage, tip_percentage
    INTO v_child_subtotal, v_child_tax, v_child_tip, v_child_total,
         v_child_tax_pct, v_child_tip_pct
    FROM private.recompute_order_bill(v_child_id);

  SELECT subtotal, tax, tip, total, tax_percentage, tip_percentage
    INTO v_parent_subtotal, v_parent_tax, v_parent_tip, v_parent_total,
         v_parent_tax_pct, v_parent_tip_pct
    FROM private.recompute_order_bill(p_parent_order_id);

  -- 10. Response.
  RETURN jsonb_build_object(
    'child_order_id', v_child_id,
    'parent', jsonb_build_object(
      'order_id', p_parent_order_id,
      'subtotal', v_parent_subtotal,
      'tax',      v_parent_tax,
      'tip',      v_parent_tip,
      'total',    v_parent_total
    ),
    'child', jsonb_build_object(
      'order_id', v_child_id,
      'subtotal', v_child_subtotal,
      'tax',      v_child_tax,
      'tip',      v_child_tip,
      'total',    v_child_total
    )
  );
END;
$$;


--
-- Name: FUNCTION split_order(p_parent_order_id uuid, p_items jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.split_order(p_parent_order_id uuid, p_items jsonb) IS 'Atomic split. SECURITY DEFINER (owner postgres). Locks the parent FOR UPDATE, validates the caller is a cashier/admin of the tenant, the parent is active|kitchen|delivered, NOT itself a partial child, NOT a delivery order, and has no payment row. Validates each line of p_items (non-empty array, <= 50 lines, uuid order_item_id, positive integer quantity, no duplicate id, item belongs to parent, quantity <= parent quantity). Rejects moving every line at full quantity (P0001 ''cannot move every item; pay the order instead''). Creates a child order (same tenant/table/waiter, status copied, is_partial_order=true, parent_order_id=parent). Full moves UPDATE the parent row order_id; partial moves shrink the parent quantity and INSERT a sibling row on the child. Both bills are recomputed by private.recompute_order_bill(). Returns jsonb with child_order_id and the parent/child bill summaries. A partial move copies the parent row stock_consumed_at to the child row, so consume_order_stock deducts every sold unit exactly once.';


--
-- Name: undo_split(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.undo_split(p_child_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_caller_tenant   uuid;
  v_caller_role     text;

  v_child           public.orders%ROWTYPE;
  v_parent          public.orders%ROWTYPE;
  v_child_item      public.order_items%ROWTYPE;
  v_match           public.order_items%ROWTYPE;

  v_parent_subtotal bigint;
  v_parent_tax      bigint;
  v_parent_tip      bigint;
  v_parent_total    bigint;
  v_parent_tax_pct  numeric;
  v_parent_tip_pct  numeric;
BEGIN
  -- 1. Caller resolution.
  v_caller_tenant := private.current_restaurant_id();
  v_caller_role   := private.current_app_role();

  IF v_caller_tenant IS NULL OR v_caller_role IS NULL THEN
    RAISE EXCEPTION 'undo_split: the caller has no profile'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_caller_role NOT IN ('cashier', 'admin') THEN
    RAISE EXCEPTION 'undo_split: only cashier or admin may undo a split'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 2. Read the child first (without lock) to learn its parent id; the
  -- tenant boundary and the partial-flag check both fire on this read. The
  -- lock is acquired later (parent first, then child) to avoid deadlocks with
  -- split_order running concurrently on the same parent.
  SELECT o.* INTO v_child
    FROM public.orders o
   WHERE o.id = p_child_order_id
     AND o.restaurant_id = v_caller_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'undo_split: order % not found', p_child_order_id
      USING ERRCODE = 'P0002';
  END IF;

  -- 3. Child rules.
  IF NOT v_child.is_partial_order OR v_child.parent_order_id IS NULL THEN
    RAISE EXCEPTION 'undo_split: order % is not a partial order', p_child_order_id
      USING ERRCODE = 'P0001';
  END IF;

  IF v_child.status IN ('paid', 'cancelled') THEN
    RAISE EXCEPTION 'undo_split: child order % has status=% (cannot undo)',
      p_child_order_id, v_child.status
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (SELECT 1 FROM public.payments p WHERE p.order_id = p_child_order_id) THEN
    RAISE EXCEPTION 'undo_split: child order % already has a payment', p_child_order_id
      USING ERRCODE = 'P0001';
  END IF;

  -- Lock the parent now that we know it is non-NULL.
  SELECT o.* INTO v_parent
    FROM public.orders o
   WHERE o.id = v_child.parent_order_id
     AND o.restaurant_id = v_caller_tenant
     FOR UPDATE;

  IF NOT FOUND OR v_parent.restaurant_id <> v_caller_tenant THEN
    RAISE EXCEPTION 'undo_split: parent order % not found', v_child.parent_order_id
      USING ERRCODE = 'P0002';
  END IF;

  -- Lock the child now (parent already locked).
  PERFORM 1 FROM public.orders o
    WHERE o.id = p_child_order_id
      AND o.restaurant_id = v_caller_tenant
      FOR UPDATE;

  -- Parent rules.
  IF v_parent.status IN ('paid', 'cancelled') THEN
    RAISE EXCEPTION 'undo_split: parent order % has status=% (cannot undo)',
      v_parent.id, v_parent.status
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (SELECT 1 FROM public.payments p WHERE p.order_id = v_parent.id) THEN
    RAISE EXCEPTION 'undo_split: parent order % already has a payment', v_parent.id
      USING ERRCODE = 'P0001';
  END IF;

  -- 4. Merge each child item back to the parent.
  FOR v_child_item IN
    SELECT oi.*
      FROM public.order_items oi
     WHERE oi.order_id = p_child_order_id
     ORDER BY oi.id
     FOR UPDATE
  LOOP
    -- Match against a parent row with the same dish_id, price, comments
    -- (NULL-safe) and status. The cheapest way to express the NULL-safety is
    -- IS NOT DISTINCT FROM.
    SELECT oi.* INTO v_match
      FROM public.order_items oi
     WHERE oi.order_id = v_parent.id
       AND oi.dish_id IS NOT DISTINCT FROM v_child_item.dish_id
       AND oi.price   IS NOT DISTINCT FROM v_child_item.price
       AND oi.comments IS NOT DISTINCT FROM v_child_item.comments
       AND oi.status  IS NOT DISTINCT FROM v_child_item.status
       AND (oi.stock_consumed_at IS NULL) = (v_child_item.stock_consumed_at IS NULL)
     LIMIT 1
     FOR UPDATE;

    IF FOUND THEN
      UPDATE public.order_items oi
         SET quantity = oi.quantity + v_child_item.quantity
       WHERE oi.id = v_match.id;

      DELETE FROM public.order_items WHERE id = v_child_item.id;
    ELSE
      UPDATE public.order_items oi
         SET order_id = v_parent.id
       WHERE oi.id = v_child_item.id;
    END IF;
  END LOOP;

  -- 5. Cleanup.
  DELETE FROM public.orders WHERE id = p_child_order_id;

  -- 6. Recompute parent.
  SELECT subtotal, tax, tip, total, tax_percentage, tip_percentage
    INTO v_parent_subtotal, v_parent_tax, v_parent_tip, v_parent_total,
         v_parent_tax_pct, v_parent_tip_pct
    FROM private.recompute_order_bill(v_parent.id);

  RETURN jsonb_build_object(
    'parent', jsonb_build_object(
      'order_id', v_parent.id,
      'subtotal', v_parent_subtotal,
      'tax',      v_parent_tax,
      'tip',      v_parent_tip,
      'total',    v_parent_total
    )
  );
END;
$$;


--
-- Name: FUNCTION undo_split(p_child_order_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.undo_split(p_child_order_id uuid) IS 'Atomic undo of a split. SECURITY DEFINER (owner postgres). Locks the parent FOR UPDATE first (parent-before-child to avoid deadlocks), then the child FOR UPDATE, validates the caller is a cashier/admin of the tenant, the child is a partial order with no payment and not paid/cancelled, and the parent has no payment and not paid/cancelled. P0002 if either order is missing or another tenant. Merges each child item back: when the parent already has a line with the same dish_id, price, comments (NULL-safe) and status, the quantities are summed and the child row deleted; otherwise the child row order_id is UPDATEd back to the parent. The child order is DELETEd and the parent bill is recomputed by private.recompute_order_bill(). Returns jsonb with the parent bill summary. Rows merge only when both have the same stock_consumed_at state (both NULL or both stamped); otherwise the child row is moved back as its own line so consume_order_stock deducts every sold unit exactly once.';


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: users; Type: TABLE; Schema: auth; Owner: -
--

CREATE TABLE auth.users (
    id uuid NOT NULL,
    email text,
    encrypted_password text,
    created_at timestamp with time zone DEFAULT now(),
    deleted_at timestamp with time zone,
    banned_until timestamp with time zone,
    raw_app_meta_data jsonb DEFAULT '{}'::jsonb,
    raw_user_meta_data jsonb DEFAULT '{}'::jsonb
);


--
-- Name: inventory_counters; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.inventory_counters (
    restaurant_id uuid NOT NULL,
    counter text NOT NULL,
    value bigint DEFAULT 0 NOT NULL
);


--
-- Name: TABLE inventory_counters; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON TABLE private.inventory_counters IS 'Per-restaurant sequences for SKUs (sku_raw, sku_prep), purchase order numbers (purchase_order) and count numbers (inventory_count). Bumped by private.next_inventory_counter only.';


--
-- Name: business_config; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.business_config (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    key character varying(100) NOT NULL,
    value text NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL
);


--
-- Name: TABLE business_config; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.business_config IS 'Per-tenant business settings (branding, tax/tip rates, NIT, role PINs). Read by every role of the tenant, written by admins only.';


--
-- Name: cash_registers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cash_registers (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    opening_timestamp timestamp with time zone NOT NULL,
    closing_timestamp timestamp with time zone,
    initial_cash numeric(10,2) NOT NULL,
    final_cash numeric(10,2),
    status character varying(20) NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    restaurant_id uuid DEFAULT private.current_restaurant_id() NOT NULL
);


--
-- Name: cash_transactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cash_transactions (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    amount numeric(10,2) NOT NULL,
    type character varying(20) NOT NULL,
    description text,
    "timestamp" timestamp with time zone DEFAULT now() NOT NULL,
    cash_register_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    restaurant_id uuid DEFAULT private.current_restaurant_id() NOT NULL,
    CONSTRAINT cash_transactions_type_check CHECK (((type)::text = ANY (ARRAY[('deposit'::character varying)::text, ('withdrawal'::character varying)::text])))
);


--
-- Name: categories; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.categories (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    name character varying(100) NOT NULL,
    description text,
    icon character varying(50) NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    restaurant_id uuid DEFAULT private.current_restaurant_id() NOT NULL
);


--
-- Name: couriers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.couriers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL,
    name text NOT NULL,
    phone text,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT couriers_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 80))),
    CONSTRAINT couriers_phone_check CHECK (((phone IS NULL) OR (phone ~ '^[0-9]{7,15}$'::text)))
);


--
-- Name: TABLE couriers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.couriers IS 'Per-tenant courier registry. Read by admin / cashier / delivery_operator of the tenant; written by admins only (couriers do not log in). Couriers do not use the app.';


--
-- Name: customer_addresses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_addresses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL,
    customer_id uuid NOT NULL,
    label text,
    address_line text NOT NULL,
    neighborhood text,
    reference text,
    is_default boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT customer_addresses_address_line_check CHECK (((length(btrim(address_line)) >= 1) AND (length(btrim(address_line)) <= 200))),
    CONSTRAINT customer_addresses_label_check CHECK (((label IS NULL) OR (length(label) <= 40))),
    CONSTRAINT customer_addresses_neighborhood_check CHECK (((neighborhood IS NULL) OR (length(neighborhood) <= 80))),
    CONSTRAINT customer_addresses_reference_check CHECK (((reference IS NULL) OR (length(reference) <= 200)))
);


--
-- Name: TABLE customer_addresses; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.customer_addresses IS 'Saved addresses per customer. ON DELETE CASCADE with the customer; at most one default per customer (partial unique index WHERE is_default). Read and written by admin / cashier / delivery_operator of the tenant; restaurant consistency with the customer is checked by a deferred constraint trigger (the same shape payments uses).';


--
-- Name: customers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL,
    phone text NOT NULL,
    name text NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT customers_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 120))),
    CONSTRAINT customers_phone_check CHECK ((phone ~ '^[0-9]{7,15}$'::text))
);


--
-- Name: TABLE customers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.customers IS 'Per-tenant customer registry keyed by phone, UNIQUE (restaurant_id, phone): the same phone may exist in two tenants, never twice in one. Read and written by admin / cashier / delivery_operator of the tenant (the operator registers unknown customers at the counter); no DELETE policy.';


--
-- Name: dishes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.dishes (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    name character varying(100) NOT NULL,
    description text,
    price numeric(10,2) NOT NULL,
    category_id uuid,
    image_url text,
    active boolean DEFAULT true NOT NULL,
    allow_comments boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    restaurant_id uuid DEFAULT private.current_restaurant_id() NOT NULL
);


--
-- Name: ingredient_categories; Type: TABLE; Schema: public; Owner: -
