--
-- Name: ingredients; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ingredients (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    name character varying(100) NOT NULL,
    description text,
    stock numeric(14,3) DEFAULT 0 NOT NULL,
    unit character varying(20) NOT NULL,
    min_stock numeric(14,3) DEFAULT 0 NOT NULL,
    category_id uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    cost numeric(14,4) DEFAULT 0,
    restaurant_id uuid DEFAULT private.current_restaurant_id() NOT NULL,
    sku text DEFAULT ''::text NOT NULL,
    kind text DEFAULT 'raw'::text NOT NULL,
    barcode text,
    max_stock numeric(14,3),
    purchase_unit character varying(20),
    purchase_factor numeric(14,4) DEFAULT 1 NOT NULL,
    default_supplier_id uuid,
    track_lots boolean DEFAULT false NOT NULL,
    shelf_life_days integer,
    is_active boolean DEFAULT true NOT NULL,
    CONSTRAINT ingredients_kind_check CHECK ((kind = ANY (ARRAY['raw'::text, 'prep'::text]))),
    CONSTRAINT ingredients_max_stock_check CHECK (((max_stock IS NULL) OR (max_stock >= (0)::numeric))),
    CONSTRAINT ingredients_purchase_factor_check CHECK ((purchase_factor > (0)::numeric)),
    CONSTRAINT ingredients_shelf_life_days_check CHECK (((shelf_life_days IS NULL) OR ((shelf_life_days >= 1) AND (shelf_life_days <= 3650)))),
    CONSTRAINT ingredients_sku_check CHECK ((sku ~ '^[A-Z0-9][A-Z0-9-]{1,31}$'::text))
);


--
-- Name: COLUMN ingredients.stock; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ingredients.stock IS 'Total stock across locations in base units. Maintained by the inventory RPCs as sum(inventory_lots.quantity).';


--
-- Name: COLUMN ingredients.kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ingredients.kind IS 'raw (bought) or prep (produced in batches from its formula in public.recipes.ingredient_id).';


--
-- Name: COLUMN ingredients.purchase_factor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ingredients.purchase_factor IS '1 purchase_unit = purchase_factor base units (unit).';


--
-- Name: inventory_count_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inventory_count_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL,
    count_id uuid NOT NULL,
    ingredient_id uuid NOT NULL,
    expected_quantity numeric(14,3) DEFAULT 0 NOT NULL,
    counted_quantity numeric(14,3),
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT inventory_count_lines_counted_quantity_check CHECK (((counted_quantity IS NULL) OR (counted_quantity >= (0)::numeric)))
);


--
-- Name: TABLE inventory_count_lines; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.inventory_count_lines IS 'Count lines: expected_quantity is the location balance snapshot at open time; admin fills counted_quantity (NULL = not counted, skipped on apply) while the count is open.';


--
-- Name: inventory_counts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inventory_counts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL,
    number integer NOT NULL,
    location_id uuid NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    notes text,
    applied_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT inventory_counts_status_check CHECK ((status = ANY (ARRAY['open'::text, 'applied'::text, 'cancelled'::text])))
);


--
-- Name: TABLE inventory_counts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.inventory_counts IS 'Physical counts per location, numbered per restaurant. Created by open_inventory_count, applied by apply_inventory_count; admin may edit notes or cancel an open count.';


--
-- Name: inventory_locations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inventory_locations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL,
    name text NOT NULL,
    code text NOT NULL,
    is_default boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT inventory_locations_code_check CHECK ((code ~ '^[A-Z0-9][A-Z0-9-]{0,31}$'::text)),
    CONSTRAINT inventory_locations_default_active_check CHECK (((NOT is_default) OR is_active)),
    CONSTRAINT inventory_locations_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 80)))
);


--
-- Name: TABLE inventory_locations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.inventory_locations IS 'Warehouses / storage locations. Exactly one is_default per restaurant ("Bodega principal", seeded on restaurant insert); the default cannot be inactive. Read by the tenant, written by admin.';


--
-- Name: inventory_lots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inventory_lots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL,
    ingredient_id uuid NOT NULL,
    location_id uuid NOT NULL,
    lot_code text,
    expires_on date,
    quantity numeric(14,3) DEFAULT 0 NOT NULL,
    unit_cost numeric(14,4) DEFAULT 0 NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT inventory_lots_lot_code_check CHECK (((lot_code IS NULL) OR ((length(btrim(lot_code)) >= 1) AND (length(btrim(lot_code)) <= 60)))),
    CONSTRAINT inventory_lots_quantity_check CHECK (((quantity >= (0)::numeric) OR ((lot_code IS NULL) AND (expires_on IS NULL)))),
    CONSTRAINT inventory_lots_unit_cost_check CHECK ((unit_cost >= (0)::numeric))
);


--
-- Name: TABLE inventory_lots; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.inventory_lots IS 'Stock per item, location and lot. The general lot (lot_code NULL, expires_on NULL) is unique per item + location and is the only one allowed to go negative (sale shortage). Read by admin and kitchen; written only by the inventory RPCs.';


--
-- Name: inventory_movements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inventory_movements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL,
    ingredient_id uuid NOT NULL,
    location_id uuid NOT NULL,
    lot_id uuid,
    movement_type text NOT NULL,
    quantity numeric(14,3) NOT NULL,
    unit_cost numeric(14,4) DEFAULT 0 NOT NULL,
    total_cost numeric(18,4) DEFAULT 0 NOT NULL,
    reason text,
    notes text,
    reference_type text,
    reference_id uuid,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT inventory_movements_movement_type_check CHECK ((movement_type = ANY (ARRAY['opening'::text, 'purchase'::text, 'sale'::text, 'production_consume'::text, 'production_output'::text, 'adjustment'::text, 'waste'::text, 'transfer_out'::text, 'transfer_in'::text, 'count_adjustment'::text]))),
    CONSTRAINT inventory_movements_quantity_check CHECK ((quantity <> (0)::numeric)),
    CONSTRAINT inventory_movements_reason_check CHECK (((reason IS NULL) OR (length(reason) <= 200)))
);


--
-- Name: TABLE inventory_movements; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.inventory_movements IS 'Signed stock ledger (positive in, negative out); total_cost = quantity * unit_cost. reference_type is one of purchase_order, production_batch, order_item, transfer, inventory_count or NULL. Admin read only; written only by the inventory RPCs.';


--
-- Name: order_deliveries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.order_deliveries (
    order_id uuid NOT NULL,
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL,
    customer_id uuid NOT NULL,
    customer_name text NOT NULL,
    customer_phone text NOT NULL,
    address_line text NOT NULL,
    neighborhood text,
    address_reference text,
    delivery_fee bigint DEFAULT 0 NOT NULL,
    payment_mode text DEFAULT 'cash_on_delivery'::text NOT NULL,
    cash_change_for bigint,
    courier_id uuid,
    delivery_status text DEFAULT 'received'::text NOT NULL,
    failure_reason text,
    dispatched_at timestamp with time zone,
    delivered_at timestamp with time zone,
    failed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    notes text,
    CONSTRAINT order_deliveries_address_line_check CHECK (((length(btrim(address_line)) >= 1) AND (length(btrim(address_line)) <= 200))),
    CONSTRAINT order_deliveries_address_reference_check CHECK (((address_reference IS NULL) OR (length(address_reference) <= 200))),
    CONSTRAINT order_deliveries_cash_change_for_check CHECK ((((payment_mode = 'cash_on_delivery'::text) AND ((cash_change_for IS NULL) OR (cash_change_for >= 0))) OR ((payment_mode = 'prepaid'::text) AND (cash_change_for IS NULL)))),
    CONSTRAINT order_deliveries_customer_name_check CHECK (((length(btrim(customer_name)) >= 1) AND (length(btrim(customer_name)) <= 120))),
    CONSTRAINT order_deliveries_customer_phone_check CHECK ((customer_phone ~ '^[0-9]{7,15}$'::text)),
    CONSTRAINT order_deliveries_delivery_fee_check CHECK ((delivery_fee >= 0)),
    CONSTRAINT order_deliveries_delivery_status_check CHECK ((delivery_status = ANY (ARRAY['received'::text, 'preparing'::text, 'ready'::text, 'out_for_delivery'::text, 'delivered'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT order_deliveries_failure_reason_check CHECK ((((delivery_status = 'failed'::text) AND (failure_reason IS NOT NULL) AND ((length(btrim(failure_reason)) >= 1) AND (length(btrim(failure_reason)) <= 200))) OR ((delivery_status <> 'failed'::text) AND ((failure_reason IS NULL) OR (length(failure_reason) <= 200))))),
    CONSTRAINT order_deliveries_neighborhood_check CHECK (((neighborhood IS NULL) OR (length(neighborhood) <= 80))),
    CONSTRAINT order_deliveries_notes_check CHECK (((notes IS NULL) OR (char_length(notes) <= 300))),
    CONSTRAINT order_deliveries_payment_mode_check CHECK ((payment_mode = ANY (ARRAY['prepaid'::text, 'cash_on_delivery'::text])))
);

ALTER TABLE ONLY public.order_deliveries REPLICA IDENTITY FULL;


--
-- Name: TABLE order_deliveries; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.order_deliveries IS '1:1 mirror of a public.orders row of type ''delivery'': the customer / address snapshot, the delivery fee, the payment mode, the courier and the lifecycle progress. Read by admin / cashier / delivery_operator / kitchen of the tenant; written ONLY by the SECURITY DEFINER RPCs of task 3 (no INSERT policy + immutability guard). Whole COP pesos (bigint).';


--
-- Name: COLUMN order_deliveries.delivery_fee; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.order_deliveries.delivery_fee IS 'Whole COP pesos, default 0; task 3 wires the configurable suggested fee and adds it to amount_due.';


--
-- Name: COLUMN order_deliveries.cash_change_for; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.order_deliveries.cash_change_for IS 'Cash the courier must hand back, only allowed when payment_mode = cash_on_delivery (CHECK). Prepaid orders never carry cash_change_for.';


--
-- Name: COLUMN order_deliveries.delivery_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.order_deliveries.delivery_status IS 'received -> preparing -> ready -> out_for_delivery -> delivered | failed (with reason) | cancelled. Transitions are enforced by the task 3 RPCs.';


--
-- Name: COLUMN order_deliveries.failure_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.order_deliveries.failure_reason IS 'Required when delivery_status = failed (CHECK); bounded to 200 characters even when the order is not failed.';


--
-- Name: order_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.order_items (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    order_id uuid,
    dish_id uuid,
    name character varying(100) NOT NULL,
    price numeric(10,2) NOT NULL,
    quantity integer NOT NULL,
    comments text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    status character varying(20) DEFAULT 'kitchen'::character varying,
    added_at timestamp with time zone DEFAULT now(),
    restaurant_id uuid DEFAULT private.current_restaurant_id() NOT NULL,
    stock_consumed_at timestamp with time zone
);

ALTER TABLE ONLY public.order_items REPLICA IDENTITY FULL;


--
-- Name: COLUMN order_items.stock_consumed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.order_items.stock_consumed_at IS 'Set by consume_order_stock when the item''s formula was deducted; a stamped item is never consumed again.';


--
-- Name: orders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.orders (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    table_id uuid,
    waiter_id uuid,
    status text DEFAULT ''::text NOT NULL,
    subtotal numeric(10,2) NOT NULL,
    tax numeric(10,2) NOT NULL,
    tax_percentage numeric(5,2) NOT NULL,
    tip numeric(10,2) DEFAULT 0 NOT NULL,
    tip_percentage numeric(5,2) DEFAULT 0 NOT NULL,
    total numeric(10,2) NOT NULL,
    is_partial_order boolean DEFAULT false NOT NULL,
    parent_order_id uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    items_json jsonb,
    total_discounts numeric(10,2) DEFAULT 0,
    restaurant_id uuid DEFAULT private.current_restaurant_id() NOT NULL,
    order_type text DEFAULT 'dine_in'::text NOT NULL,
    CONSTRAINT orders_order_type_check CHECK ((order_type = ANY (ARRAY['dine_in'::text, 'delivery'::text]))),
    CONSTRAINT orders_order_type_table_id_check CHECK (((order_type = 'dine_in'::text) OR (table_id IS NULL))),
    CONSTRAINT orders_status_check CHECK ((status = ANY (ARRAY['active'::text, 'kitchen'::text, 'delivered'::text, 'cancelled'::text, 'paid'::text])))
);

ALTER TABLE ONLY public.orders REPLICA IDENTITY FULL;


--
-- Name: COLUMN orders.order_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orders.order_type IS '''dine_in'' (default; the original model) or ''delivery''. A delivery row must have table_id IS NULL (CHECK). Existing rows stay dine_in.';


--
-- Name: payment_methods; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payment_methods (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    kind text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT payment_methods_code_check CHECK ((code ~ '^[a-z0-9_]{2,32}$'::text)),
    CONSTRAINT payment_methods_kind_check CHECK ((kind = ANY (ARRAY['cash'::text, 'electronic'::text]))),
    CONSTRAINT payment_methods_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 60)))
);


--
-- Name: TABLE payment_methods; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.payment_methods IS 'Per-tenant catalog of payment methods. Read by every role of the tenant (inactive rows included, so order history still resolves a method that was deactivated later), written by admins only. `kind = ''cash''` is the only value that gives change - there is no second column for it.';


--
-- Name: COLUMN payment_methods.code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payment_methods.code IS 'Stable key the payment rows carry. Unique per tenant and immutable after insert (public.guard_payment_methods_code_immutable).';


--
-- Name: COLUMN payment_methods.kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payment_methods.kind IS '''cash'' gives change, ''electronic'' does not. This column is the whole rule: do not add a parallel boolean.';


--
-- Name: COLUMN payment_methods.is_active; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payment_methods.is_active IS 'Soft delete. The row is kept so historical payments keep resolving their method; filter on it in the checkout picker query, not in the row-level read.';


--
-- Name: payment_tenders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payment_tenders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL,
    payment_id uuid NOT NULL,
    line_no smallint NOT NULL,
    payment_method_id uuid NOT NULL,
    method_code text NOT NULL,
    method_kind text NOT NULL,
    amount bigint NOT NULL,
    cash_received bigint,
    CONSTRAINT payment_tenders_amount_check CHECK ((amount > 0)),
    CONSTRAINT payment_tenders_cash_received_check CHECK ((((method_kind = 'cash'::text) AND (cash_received IS NOT NULL) AND (cash_received >= amount)) OR ((method_kind = 'electronic'::text) AND (cash_received IS NULL)))),
    CONSTRAINT payment_tenders_line_no_check CHECK ((line_no >= 1)),
    CONSTRAINT payment_tenders_method_kind_check CHECK ((method_kind = ANY (ARRAY['cash'::text, 'electronic'::text])))
);


--
-- Name: TABLE payment_tenders; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.payment_tenders IS 'The tender lines of one payment (UNIQUE (payment_id, line_no)): how a single bill was split across methods. method_code and method_kind are validated against the public.payment_methods catalog row at insert time and then frozen as history, so a later rename or retype does not rewrite history. Written only by public.pay_order.';


--
-- Name: COLUMN payment_tenders.cash_received; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payment_tenders.cash_received IS 'What the customer handed over for this line. Required for a cash tender and must be >= amount; forbidden (NULL) for an electronic one. This CHECK is the whole "only cash gives change" rule.';


--
-- Name: payment_transactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payment_transactions (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    order_id uuid NOT NULL,
    table_id uuid,
    amount numeric(10,2) NOT NULL,
    method character varying(20) NOT NULL,
    cash_received numeric(10,2),
    cash_change numeric(10,2),
    "timestamp" timestamp with time zone NOT NULL,
    cash_register_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    waiter_id uuid,
    tip_amount numeric(10,2) DEFAULT 0,
    total_discounts numeric(10,2) DEFAULT 0,
    restaurant_id uuid DEFAULT private.current_restaurant_id() NOT NULL
);


--
-- Name: TABLE payment_transactions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.payment_transactions IS 'LEGACY history, superseded by public.payments + public.payment_tenders (numeric(10,2) money, free-text method, no tender lines, written only by the retired public.complete_payment). Kept readable so old orders and reports keep rendering; read-only for every authenticated caller. Do not write here - public.pay_order is the only writer of the ledger.';


--
-- Name: payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL,
    order_id uuid NOT NULL,
    cash_register_id uuid NOT NULL,
    cashier_profile_id uuid,
    amount_due bigint NOT NULL,
    tip_amount bigint DEFAULT 0 NOT NULL,
    total_charged bigint NOT NULL,
    change_given bigint DEFAULT 0 NOT NULL,
    idempotency_key uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT payments_amount_due_check CHECK ((amount_due >= 0)),
    CONSTRAINT payments_change_given_check CHECK ((change_given >= 0)),
    CONSTRAINT payments_tip_amount_check CHECK ((tip_amount >= 0)),
    CONSTRAINT payments_total_charged_check CHECK ((total_charged = (amount_due + tip_amount)))
);


--
-- Name: TABLE payments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.payments IS 'One row per settled order (UNIQUE order_id): the bill, the tip, the total charged, the change handed back and the drawer it was taken on. Money is whole COP pesos (bigint). Written only by public.pay_order; readable by every role of the tenant and writable by none of them.';


--
-- Name: COLUMN payments.cashier_profile_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.cashier_profile_id IS 'Staff member who took the payment. ON DELETE SET NULL: removing a profile must not delete money history.';


--
-- Name: COLUMN payments.total_charged; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.total_charged IS 'Must equal amount_due + tip_amount (CHECK) and must equal the sum of its tender amounts (deferred constraint trigger).';


--
-- Name: COLUMN payments.change_given; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.change_given IS 'Must equal the sum of (cash_received - amount) over the cash tenders (deferred constraint trigger).';


--
-- Name: COLUMN payments.idempotency_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.idempotency_key IS 'Key generated per checkout attempt, UNIQUE per (restaurant_id, idempotency_key). The same uuid may be reused by another tenant.';


--
-- Name: production_batches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.production_batches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL,
    ingredient_id uuid NOT NULL,
    location_id uuid NOT NULL,
    quantity numeric(14,3) NOT NULL,
    lot_id uuid,
    unit_cost numeric(14,4) DEFAULT 0 NOT NULL,
    total_cost numeric(18,4) DEFAULT 0 NOT NULL,
    expires_on date,
    notes text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT production_batches_quantity_check CHECK ((quantity > (0)::numeric))
);


--
-- Name: TABLE production_batches; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.production_batches IS 'One row per produce_preparation call: output quantity, the lot it created and its computed unit cost. Read by admin and kitchen; written only by the RPC.';


--
-- Name: profiles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.profiles (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    full_name character varying(100) NOT NULL,
    username character varying(50),
    email character varying(100),
    role character varying(20) NOT NULL,
