);


--
-- Name: purchase_order_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.purchase_order_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL,
    purchase_order_id uuid NOT NULL,
    ingredient_id uuid NOT NULL,
    quantity numeric(14,3) NOT NULL,
    unit_cost numeric(14,4) DEFAULT 0 NOT NULL,
    received_quantity numeric(14,3) DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT purchase_order_lines_quantity_check CHECK ((quantity > (0)::numeric)),
    CONSTRAINT purchase_order_lines_received_quantity_check CHECK ((received_quantity >= (0)::numeric)),
    CONSTRAINT purchase_order_lines_unit_cost_check CHECK ((unit_cost >= (0)::numeric))
);


--
-- Name: TABLE purchase_order_lines; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.purchase_order_lines IS 'Purchase order lines; quantity and unit_cost in base units. received_quantity is written only by receive_purchase_order. Admin only; editable while the order is draft or ordered.';


--
-- Name: purchase_orders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.purchase_orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL,
    number integer NOT NULL,
    supplier_id uuid NOT NULL,
    location_id uuid NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    expected_on date,
    payment_status text DEFAULT 'pending'::text NOT NULL,
    notes text,
    ordered_at timestamp with time zone,
    received_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT purchase_orders_payment_status_check CHECK ((payment_status = ANY (ARRAY['pending'::text, 'paid'::text]))),
    CONSTRAINT purchase_orders_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'ordered'::text, 'partially_received'::text, 'received'::text, 'cancelled'::text])))
);


--
-- Name: TABLE purchase_orders; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.purchase_orders IS 'Purchase orders, numbered per restaurant. Admin only. draft -> ordered -> partially_received -> received (the last two only through receive_purchase_order); draft | ordered -> cancelled.';


--
-- Name: recipe_ingredients; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.recipe_ingredients (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    recipe_id uuid NOT NULL,
    ingredient_id uuid NOT NULL,
    quantity numeric(14,4) NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    restaurant_id uuid DEFAULT private.current_restaurant_id() NOT NULL
);


--
-- Name: recipes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.recipes (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    dish_id uuid,
    created_at timestamp with time zone DEFAULT now(),
    restaurant_id uuid DEFAULT private.current_restaurant_id() NOT NULL,
    ingredient_id uuid,
    yield_quantity numeric(14,3) DEFAULT 1 NOT NULL,
    notes text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT recipes_target_check CHECK ((num_nonnulls(dish_id, ingredient_id) = 1)),
    CONSTRAINT recipes_yield_quantity_check CHECK ((yield_quantity > (0)::numeric))
);


--
-- Name: COLUMN recipes.ingredient_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.recipes.ingredient_id IS 'Preparation produced by this formula (kind = prep). Exactly one of dish_id / ingredient_id is set.';


--
-- Name: COLUMN recipes.yield_quantity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.recipes.yield_quantity IS 'Output quantity (in the target unit) the listed lines produce; 1 portion for dishes.';


--
-- Name: restaurants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.restaurants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    timezone text DEFAULT 'America/Bogota'::text NOT NULL,
    currency text DEFAULT 'COP'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: suppliers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.suppliers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid DEFAULT private.default_restaurant_id() NOT NULL,
    name text NOT NULL,
    tax_id text,
    contact_name text,
    phone text,
    email text,
    lead_time_days integer,
    notes text,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT suppliers_contact_name_check CHECK (((contact_name IS NULL) OR (length(contact_name) <= 120))),
    CONSTRAINT suppliers_email_check CHECK (((email IS NULL) OR (length(email) <= 160))),
    CONSTRAINT suppliers_lead_time_days_check CHECK (((lead_time_days IS NULL) OR ((lead_time_days >= 0) AND (lead_time_days <= 365)))),
    CONSTRAINT suppliers_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 120))),
    CONSTRAINT suppliers_phone_check CHECK (((phone IS NULL) OR (length(phone) <= 30))),
    CONSTRAINT suppliers_tax_id_check CHECK (((tax_id IS NULL) OR (length(tax_id) <= 30)))
);


--
-- Name: TABLE suppliers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.suppliers IS 'Per-tenant supplier registry. Admin only (read and write); soft delete through is_active.';


--
-- Name: tables; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tables (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    number integer NOT NULL,
    status character varying(20) DEFAULT 'available'::character varying NOT NULL,
    waiter_id uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    restaurant_id uuid DEFAULT private.current_restaurant_id() NOT NULL
);

ALTER TABLE ONLY public.tables REPLICA IDENTITY FULL;


